INSERT INTO `quick_revision` VALUES (1,13,'Geography Quick Revision','[{\"q\":\"What is the capital of France?\",\"a\":\"Paris\"},{\"q\":\"What process converts light to energy?\",\"a\":\"Photosynthesis\"},{\"q\":\"How many planets are in the solar system?\",\"a\":\"8 planets\"},{\"q\":\"How much of Earth surface is water?\",\"a\":\"71%\"},{\"q\":\"What is the highest peak on Earth?\",\"a\":\"Mount Everest\"}]','This chapter covers basic geography concepts including capitals, natural processes, and planetary facts.','2025-12-30 13:59:35'),(13,15,'EARLY HUMANS','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\"},{\"q\":\"Who were early humans?\",\"a\":\"Early humans were the first people who lived long ago. They depended on nature for food, shelter, and protection.\"},{\"q\":\"What kind of life did early humans lead?\",\"a\":\"Early humans led a nomadic life. They moved from place to place in search of food, water, and shelter.\"},{\"q\":\"Why did early humans live a nomadic life?\",\"a\":\"Early humans did not know farming. They moved to find food, water, and safe shelter.\"},{\"q\":\"Where did early humans live?\",\"a\":\"Early humans lived in caves and on branches of trees to protect themselves from wild animals and bad weather.\"},{\"q\":\"What were early humans called and why?\",\"a\":\"Early humans were called hunters and gatherers because they hunted animals and gathered fruits, roots, and eggs.\"},{\"q\":\"What food did early humans eat?\",\"a\":\"Early humans ate meat of animals and birds, fruits, roots, and eggs collected from nature.\"},{\"q\":\"What clothes did early humans wear?\",\"a\":\"Early humans did not wear stitched clothes. They used leaves, tree bark, and animal skin to cover their bodies.\"},{\"q\":\"What tools did early humans use?\",\"a\":\"Early humans mostly used stone tools. Sometimes tools were also made from animal bones and horns.\"},{\"q\":\"Why were stone tools important?\",\"a\":\"Stone tools helped early humans hunt animals, cut meat, and dig roots from the ground.\"},{\"q\":\"How did early humans improve their tools?\",\"a\":\"They tied sharp stones to wooden sticks. This helped them hunt animals from a distance.\"},{\"q\":\"How was fire discovered?\",\"a\":\"Fire was discovered when early humans rubbed two stones together and produced sparks.\"},{\"q\":\"What were the uses of fire?\",\"a\":\"Fire was used for cooking food, keeping warm, giving light, and protecting from wild animals.\"},{\"q\":\"Why was the discovery of fire important?\",\"a\":\"Fire improved daily life and played a major role in the development of human civilisation.\"},{\"q\":\"How did early humans begin farming?\",\"a\":\"Early humans noticed that seeds thrown on the ground grew into plants. This led to farming.\"},{\"q\":\"What is farming?\",\"a\":\"Farming means growing crops for food. It helped humans produce their own food.\"},{\"q\":\"How did farming change human life?\",\"a\":\"Farming allowed humans to stay in one place and start a settled life.\"},{\"q\":\"How was the wheel invented?\",\"a\":\"Early humans saw a log rolling down a hill. This gave them the idea of the wheel.\"},{\"q\":\"What were the uses of the wheel?\",\"a\":\"The wheel helped in carrying heavy loads, making carts, pottery, and weaving clothes.\"},{\"q\":\"Why was the wheel an important invention?\",\"a\":\"The wheel made work easier and improved transport and daily life.\"},{\"q\":\"What is pottery?\",\"a\":\"Pottery is the art of making pots. Early humans used the wheel to make pots.\"},{\"q\":\"What is a settled life?\",\"a\":\"A settled life means living in one place permanently instead of moving from place to place.\"},{\"q\":\"How did farming and the wheel help humans live a settled life?\",\"a\":\"Farming provided regular food and the wheel made daily work easier.\"},{\"q\":\"Which discoveries helped in the development of civilisation?\",\"a\":\"The discovery of fire, farming, and the invention of the wheel helped develop civilisation.\"},{\"q\":\"Why are early humans associated with the Stone Age?\",\"a\":\"Early humans mainly used stone tools. Therefore, this period is called the Stone Age.\"},{\"q\":\"How did caves help early humans?\",\"a\":\"Caves gave shelter and protected early humans from wild animals and harsh weather.\"},{\"q\":\"How did early humans protect themselves from wild animals?\",\"a\":\"Early humans used fire and lived in safe places like caves.\"},{\"q\":\"What changes occurred in human life over time?\",\"a\":\"Humans discovered fire, farming, and the wheel which improved their lifestyle.\"},{\"q\":\"Why is it important to study early human life?\",\"a\":\"It helps us understand how human civilisation developed step by step.\"}]','EARLY HUMANS','2026-01-04 14:12:38'),(21,16,'थेंब','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\"},{\"q\":\"\\u0925\\u0947\\u0902\\u092c \\u0915\\u094b\\u0923\\u0924\\u094d\\u092f\\u093e \\u0920\\u093f\\u0915\\u093e\\u0923\\u0940 \\u092c\\u0938\\u0932\\u0947 \\u0939\\u094b\\u0924\\u0947 \\u0924\\u0947 \\u0938\\u0935\\u093f\\u0938\\u094d\\u0924\\u0930 \\u0938\\u093e\\u0902\\u0917\\u093e.\",\"a\":\"\\u0925\\u0947\\u0902\\u092c \\u0906\\u0915\\u093e\\u0936\\u093e\\u0924\\u0942\\u0928 \\u092f\\u0947\\u090a\\u0928 \\u091b\\u094b\\u091f\\u094d\\u092f\\u093e \\u091b\\u094b\\u091f\\u094d\\u092f\\u093e \\u092a\\u093e\\u0928\\u093e\\u0902\\u0935\\u0930 \\u092c\\u0938\\u0932\\u0947 \\u0939\\u094b\\u0924\\u0947. \\u0924\\u0947 \\u092a\\u093e\\u0928\\u093e\\u0902\\u0935\\u0930 \\u0905\\u0932\\u0917\\u0926 \\u092c\\u0938\\u0942\\u0928 \\u0939\\u0935\\u0947\\u0924 \\u0939\\u0932\\u0915\\u0947\\u091a \\u0921\\u094b\\u0932\\u0924 \\u0939\\u094b\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u091a\\u0947 \\u0938\\u0941\\u0902\\u0926\\u0930 \\u0926\\u0943\\u0936\\u094d\\u092f \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0915\\u0930\\u0924 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"\\u0915\\u0935\\u093f\\u0924\\u0947\\u0924 \\u0925\\u0947\\u0902\\u092c \\u0915\\u0936\\u093e\\u092a\\u094d\\u0930\\u0915\\u093e\\u0930\\u0947 \\u0939\\u093e\\u0932\\u091a\\u093e\\u0932 \\u0915\\u0930\\u0924\\u093e\\u0928\\u093e \\u0926\\u093e\\u0916\\u0935\\u0932\\u0947 \\u0906\\u0939\\u0947\\u0924?\",\"a\":\"\\u0915\\u0935\\u093f\\u0924\\u0947\\u0924 \\u0925\\u0947\\u0902\\u092c \\u0935\\u093e\\u0939\\u0924\\u094d\\u092f\\u093e \\u0939\\u0935\\u0947\\u0924 \\u0921\\u094b\\u0932\\u0924 \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0938\\u093e\\u0902\\u0917\\u093f\\u0924\\u0932\\u0947 \\u0906\\u0939\\u0947. \\u0924\\u0947 \\u0938\\u094d\\u0925\\u093f\\u0930 \\u0928 \\u0930\\u093e\\u0939\\u0924\\u093e \\u0939\\u0932\\u0915\\u0947\\u091a \\u0907\\u0915\\u0921\\u0947 \\u0924\\u093f\\u0915\\u0921\\u0947 \\u0939\\u0932\\u0924 \\u0905\\u0938\\u0924\\u093e\\u0924.\"},{\"q\":\"\\u0925\\u0947\\u0902\\u092c \\u0906\\u0923\\u093f \\u0907\\u0902\\u0926\\u094d\\u0930\\u0927\\u0928\\u0941\\u0937\\u094d\\u092f \\u092f\\u093e\\u0902\\u091a\\u093e \\u0938\\u0902\\u092c\\u0902\\u0927 \\u0938\\u094d\\u092a\\u0937\\u094d\\u091f \\u0915\\u0930\\u093e.\",\"a\":\"\\u0925\\u0947\\u0902\\u092c \\u0907\\u0902\\u0926\\u094d\\u0930\\u0927\\u0928\\u0941\\u0937\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0938\\u0941\\u0902\\u0926\\u0930 \\u0930\\u0902\\u0917 \\u0926\\u093e\\u0916\\u0935\\u0924\\u093e\\u0924. \\u092a\\u093e\\u0935\\u0938\\u093e\\u091a\\u094d\\u092f\\u093e \\u0925\\u0947\\u0902\\u092c\\u093e\\u0902\\u092e\\u0941\\u0933\\u0947 \\u0906\\u0915\\u093e\\u0936\\u093e\\u0924 \\u0907\\u0902\\u0926\\u094d\\u0930\\u0927\\u0928\\u0941\\u0937\\u094d\\u092f \\u0926\\u093f\\u0938\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0926\\u0943\\u0936\\u094d\\u092f \\u0905\\u0927\\u093f\\u0915 \\u0906\\u0915\\u0930\\u094d\\u0937\\u0915 \\u092c\\u0928\\u0924\\u0947.\"},{\"q\":\"\\u0925\\u0947\\u0902\\u092c \\u0915\\u094b\\u0935\\u0933\\u094d\\u092f\\u093e \\u0917\\u0935\\u0924\\u093e\\u0935\\u0930 \\u091d\\u094b\\u092a\\u0932\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0915\\u0935\\u093f\\u0924\\u0947\\u0924 \\u0915\\u093e \\u0938\\u093e\\u0902\\u0917\\u093f\\u0924\\u0932\\u0947 \\u0906\\u0939\\u0947?\",\"a\":\"\\u092a\\u093e\\u0935\\u0938\\u093e\\u091a\\u0947 \\u0925\\u0947\\u0902\\u092c \\u091c\\u092e\\u093f\\u0928\\u0940\\u0935\\u0930 \\u092a\\u0921\\u0942\\u0928 \\u0917\\u0935\\u0924\\u093e\\u0932\\u093e \\u0924\\u093e\\u091c\\u0947\\u092a\\u0923\\u093e \\u0926\\u0947\\u0924\\u093e\\u0924. \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0915\\u0935\\u093f\\u0924\\u0947\\u0924 \\u0925\\u0947\\u0902\\u092c \\u0915\\u094b\\u0935\\u0933\\u094d\\u092f\\u093e \\u0917\\u0935\\u0924\\u093e\\u0935\\u0930 \\u091d\\u094b\\u092a\\u0932\\u0947 \\u0905\\u0938\\u0947 \\u0938\\u093e\\u0902\\u0917\\u093f\\u0924\\u0932\\u0947 \\u0906\\u0939\\u0947.\"},{\"q\":\"\\u0925\\u0947\\u0902\\u092c \\u0915\\u0935\\u093f\\u0924\\u0947\\u092e\\u0941\\u0933\\u0947 \\u0906\\u092a\\u0932\\u094d\\u092f\\u093e\\u0932\\u093e \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u092c\\u0926\\u094d\\u0926\\u0932 \\u0915\\u093e\\u092f \\u0936\\u093f\\u0915\\u093e\\u092f\\u0932\\u093e \\u092e\\u093f\\u0933\\u0924\\u0947?\",\"a\":\"\\u0939\\u0940 \\u0915\\u0935\\u093f\\u0924\\u093e \\u0906\\u092a\\u0932\\u094d\\u092f\\u093e\\u0932\\u093e \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u091a\\u0947 \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f \\u0913\\u0933\\u0916\\u093e\\u092f\\u0932\\u093e \\u0936\\u093f\\u0915\\u0935\\u0924\\u0947. \\u0932\\u0939\\u093e\\u0928 \\u0932\\u0939\\u093e\\u0928 \\u0925\\u0947\\u0902\\u092c\\u0939\\u0940 \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0915\\u093f\\u0924\\u0940 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u0905\\u0938\\u0924\\u093e\\u0924 \\u0939\\u0947 \\u0938\\u092e\\u091c\\u0924\\u0947.\"}]','थेंब','2026-01-10 09:06:09'),(22,77,'INDUS VALLEY CIVILSATION','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explanation\"},{\"q\":\"What is the Indus Valley Civilisation?\",\"a\":\"It was the earliest civilisation in the Indian subcontinent.\",\"e\":\"\\u0938\\u093f\\u0902\\u0927\\u0942 \\u0916\\u094b\\u0930\\u0947 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0939\\u0940 \\u092d\\u093e\\u0930\\u0924\\u0940\\u092f \\u0909\\u092a\\u0916\\u0902\\u0921\\u093e\\u0924\\u0940\\u0932 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u092a\\u094d\\u0930\\u093e\\u091a\\u0940\\u0928 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0939\\u094b\\u0924\\u0940. \\u092f\\u0947\\u0925\\u0947 \\u0932\\u094b\\u0915 \\u090f\\u0915\\u0924\\u094d\\u0930 \\u0930\\u093e\\u0939\\u0942\\u0928 \\u0928\\u093f\\u092f\\u094b\\u091c\\u0928\\u092c\\u0926\\u094d\\u0927 \\u091c\\u0940\\u0935\\u0928 \\u091c\\u0917\\u0924 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"When did the Indus Valley Civilisation flourish?\",\"a\":\"It flourished between 2500 and 1500 BCE.\",\"e\":\"\\u0939\\u0940 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0907.\\u0938.\\u092a\\u0942. \\u0968\\u096b\\u0966\\u0966 \\u0924\\u0947 \\u0967\\u096b\\u0966\\u0966 \\u092f\\u093e \\u0915\\u093e\\u0933\\u093e\\u0924 \\u0935\\u093f\\u0915\\u0938\\u093f\\u0924 \\u091d\\u093e\\u0932\\u0940.\"},{\"q\":\"Where was the Indus Valley Civilisation located?\",\"a\":\"It was located around the Indus river and its tributaries.\",\"e\":\"\\u0939\\u0940 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0938\\u093f\\u0902\\u0927\\u0942 \\u0928\\u0926\\u0940 \\u0935 \\u0924\\u093f\\u091a\\u094d\\u092f\\u093e \\u0909\\u092a\\u0928\\u0926\\u094d\\u092f\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0906\\u0938\\u092a\\u093e\\u0938 \\u0935\\u0938\\u0932\\u0947\\u0932\\u0940 \\u0939\\u094b\\u0924\\u0940.\"},{\"q\":\"Name any two cities of the Indus Valley Civilisation.\",\"a\":\"Harappa and Mohenjo-daro.\",\"e\":\"\\u0939\\u0930\\u092a\\u094d\\u092a\\u093e \\u0906\\u0923\\u093f \\u092e\\u094b\\u0939\\u0928\\u091c\\u094b\\u0926\\u0921\\u094b \\u0939\\u0940 \\u0938\\u093f\\u0902\\u0927\\u0942 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940\\u0924\\u0940\\u0932 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0936\\u0939\\u0930\\u0947 \\u0939\\u094b\\u0924\\u0940.\"},{\"q\":\"What were the houses made of?\",\"a\":\"They were made of baked bricks.\",\"e\":\"\\u0918\\u0930\\u0947 \\u092d\\u093e\\u091c\\u0932\\u0947\\u0932\\u094d\\u092f\\u093e \\u0935\\u093f\\u091f\\u093e\\u0902\\u0928\\u0940 \\u092c\\u093e\\u0902\\u0927\\u0932\\u0947\\u0932\\u0940 \\u0939\\u094b\\u0924\\u0940, \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u0940 \\u092e\\u091c\\u092c\\u0942\\u0924 \\u0939\\u094b\\u0924\\u0940.\"},{\"q\":\"Which building was used to store grains?\",\"a\":\"The Great Granary.\",\"e\":\"\\u092e\\u0939\\u093e\\u0928 \\u0927\\u093e\\u0928\\u094d\\u092f\\u0915\\u094b\\u0920\\u093e\\u0930\\u093e\\u0924 \\u0905\\u0928\\u094d\\u0928\\u0927\\u093e\\u0928\\u094d\\u092f \\u0938\\u093e\\u0920\\u0935\\u0932\\u0947 \\u091c\\u093e\\u0924 \\u0905\\u0938\\u0947.\"},{\"q\":\"What crops did the people grow?\",\"a\":\"Wheat, rice and barley.\",\"e\":\"\\u0936\\u0947\\u0924\\u0940 \\u0939\\u093e \\u092e\\u0941\\u0916\\u094d\\u092f \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0905\\u0938\\u0942\\u0928 \\u0917\\u0939\\u0942, \\u0924\\u093e\\u0902\\u0926\\u0942\\u0933 \\u0906\\u0923\\u093f \\u092c\\u093e\\u0930\\u094d\\u0932\\u0940 \\u092a\\u093f\\u0915\\u0947 \\u0918\\u0947\\u0924\\u0932\\u0940 \\u091c\\u093e\\u0924.\"},{\"q\":\"What did the Indus people worship?\",\"a\":\"They worshipped nature.\",\"e\":\"\\u0938\\u093f\\u0902\\u0927\\u0942 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940\\u0924\\u0940\\u0932 \\u0932\\u094b\\u0915 \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u092a\\u0942\\u091c\\u0915 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe the town planning of Indus cities.\",\"a\":\"Cities had straight roads and proper drainage.\",\"e\":\"\\u0936\\u0939\\u0930\\u0947 \\u0928\\u093f\\u092f\\u094b\\u091c\\u0928\\u092c\\u0926\\u094d\\u0927 \\u0939\\u094b\\u0924\\u0940. \\u0930\\u0938\\u094d\\u0924\\u0947 \\u0938\\u0930\\u0933 \\u0935 \\u0930\\u0941\\u0902\\u0926 \\u0939\\u094b\\u0924\\u0947 \\u0924\\u0938\\u0947\\u091a \\u091d\\u093e\\u0915\\u0932\\u0947\\u0932\\u0940 \\u0928\\u093f\\u091a\\u0930\\u093e \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u0939\\u094b\\u0924\\u0940.\"},{\"q\":\"Explain the importance of the Great Bath.\",\"a\":\"It was a large water tank for special occasions.\",\"e\":\"\\u092e\\u0939\\u093e\\u0928 \\u0938\\u094d\\u0928\\u093e\\u0928\\u0917\\u0943\\u0939 \\u0927\\u093e\\u0930\\u094d\\u092e\\u093f\\u0915 \\u0915\\u093f\\u0902\\u0935\\u093e \\u0935\\u093f\\u0936\\u0947\\u0937 \\u092a\\u094d\\u0930\\u0938\\u0902\\u0917\\u0940 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0947 \\u091c\\u093e\\u0924 \\u0905\\u0938\\u093e\\u0935\\u0947 \\u0905\\u0938\\u0947 \\u092e\\u093e\\u0928\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"What occupations did the people follow?\",\"a\":\"Farming, crafts, trade and building.\",\"e\":\"\\u0932\\u094b\\u0915 \\u0936\\u0947\\u0924\\u0940, \\u0915\\u093e\\u0930\\u093e\\u0917\\u093f\\u0930\\u0940, \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930 \\u0935 \\u092c\\u093e\\u0902\\u0927\\u0915\\u093e\\u092e \\u0905\\u0936\\u0940 \\u0915\\u093e\\u092e\\u0947 \\u0915\\u0930\\u0924.\"},{\"q\":\"Describe the lifestyle of Indus people.\",\"a\":\"They lived an organised life.\",\"e\":\"\\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u0947 \\u091c\\u0940\\u0935\\u0928 \\u0936\\u093f\\u0938\\u094d\\u0924\\u092c\\u0926\\u094d\\u0927 \\u0935 \\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"How did people communicate?\",\"a\":\"Through picture symbols.\",\"e\":\"\\u0932\\u094b\\u0915 \\u091a\\u093f\\u0924\\u094d\\u0930\\u0947 \\u0935 \\u091a\\u093f\\u0928\\u094d\\u0939\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e\\u093e\\u0924\\u0942\\u0928 \\u0938\\u0902\\u0935\\u093e\\u0926 \\u0938\\u093e\\u0927\\u0924.\"},{\"q\":\"What were the possible reasons for decline?\",\"a\":\"Floods, diseases and earthquakes.\",\"e\":\"\\u092a\\u0942\\u0930, \\u0930\\u094b\\u0917\\u0930\\u093e\\u0908 \\u0935 \\u092d\\u0942\\u0915\\u0902\\u092a \\u0939\\u0940 \\u0931\\u094d\\u0939\\u093e\\u0938\\u093e\\u091a\\u0940 \\u0915\\u093e\\u0930\\u0923\\u0947 \\u0905\\u0938\\u093e\\u0935\\u0940\\u0924 \\u0905\\u0938\\u0947 \\u092e\\u093e\\u0928\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Why is the Indus Valley Civilisation important?\",\"a\":\"It shows early planned urban life.\",\"e\":\"\\u0939\\u0940 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0928\\u093f\\u092f\\u094b\\u091c\\u0928\\u092c\\u0926\\u094d\\u0927 \\u0936\\u0939\\u0930\\u0940 \\u091c\\u0940\\u0935\\u0928\\u093e\\u091a\\u0940 \\u0938\\u0941\\u0930\\u0941\\u0935\\u093e\\u0924 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0924\\u0947.\"}]','INDUS VALLEY CIVILISATION','2026-01-14 19:56:25'),(23,78,'OUR GOVERNMENT','[{\"q\":\"What is government? (Short Answer)\",\"a\":\"A group of elected members who run the country.\",\"e\":\"\\u0936\\u093e\\u0938\\u0928 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0926\\u0947\\u0936\\u093e\\u0924\\u0940\\u0932 \\u091c\\u0928\\u0924\\u0947\\u0928\\u0947 \\u0928\\u093f\\u0935\\u0921\\u0942\\u0928 \\u0926\\u093f\\u0932\\u0947\\u0932\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940\\u0902\\u091a\\u093e \\u0938\\u092e\\u0942\\u0939 \\u0939\\u094b\\u092f. \\u0939\\u0947 \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940 \\u0926\\u0947\\u0936\\u093e\\u091a\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e\\u092a\\u0928 \\u0935 \\u091c\\u0928\\u0915\\u0932\\u094d\\u092f\\u093e\\u0923\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924\\u093e\\u0924.\"},{\"q\":\"Where is the Central Government of India based? (Short Answer)\",\"a\":\"New Delhi.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0947 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0928\\u0935\\u0940 \\u0926\\u093f\\u0932\\u094d\\u0932\\u0940 \\u092f\\u0947\\u0925\\u0947 \\u0906\\u0939\\u0947. \\u0928\\u0935\\u0940 \\u0926\\u093f\\u0932\\u094d\\u0932\\u0940 \\u0939\\u0940 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0940 \\u0930\\u093e\\u091c\\u0927\\u093e\\u0928\\u0940 \\u0906\\u0939\\u0947.\"},{\"q\":\"How many levels of government are there in India? (Short Answer)\",\"a\":\"Three levels.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0936\\u093e\\u0938\\u0928 \\u0924\\u0940\\u0928 \\u0938\\u094d\\u0924\\u0930\\u093e\\u0902\\u0935\\u0930 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0930\\u0924\\u0947 \\u2013 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928, \\u0930\\u093e\\u091c\\u094d\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0906\\u0923\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928.\"},{\"q\":\"Name the three levels of government in India. (Long Answer)\",\"a\":\"Central, State and Local Government.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0936\\u093e\\u0938\\u0928\\u093e\\u091a\\u0940 \\u0924\\u0940\\u0928 \\u092a\\u093e\\u0924\\u0933\\u0940 \\u0906\\u0939\\u0947\\u0924. \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0926\\u0947\\u0936\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0927\\u094b\\u0930\\u0923\\u0947 \\u0920\\u0930\\u0935\\u0924\\u0947, \\u0930\\u093e\\u091c\\u094d\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928 \\u092a\\u093e\\u0939\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928 \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u092e\\u0942\\u0932\\u092d\\u0942\\u0924 \\u0917\\u0930\\u091c\\u093e\\u0902\\u091a\\u0940 \\u0915\\u093e\\u0933\\u091c\\u0940 \\u0918\\u0947\\u0924\\u0947.\"},{\"q\":\"What are the main functions of the Central Government? (Long Answer)\",\"a\":\"Defence, foreign trade, railways and national welfare.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0926\\u0947\\u0936\\u093e\\u091a\\u0947 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0915\\u0930\\u0923\\u0947, \\u092a\\u0930\\u0915\\u0940\\u092f \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930 \\u0935 \\u0906\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0938\\u0902\\u092c\\u0902\\u0927 \\u0938\\u093e\\u0902\\u092d\\u093e\\u0933\\u0923\\u0947, \\u0930\\u0947\\u0932\\u094d\\u0935\\u0947 \\u0935 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0930\\u0938\\u094d\\u0924\\u094d\\u092f\\u093e\\u0902\\u091a\\u0940 \\u0926\\u0947\\u0916\\u092d\\u093e\\u0932 \\u0915\\u0930\\u0923\\u0947 \\u0924\\u0938\\u0947\\u091a \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u0915\\u0932\\u094d\\u092f\\u093e\\u0923\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924\\u0947.\"},{\"q\":\"Who are part of the Central Government? (Short Answer)\",\"a\":\"President, Prime Minister and Ministers.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u092a\\u0924\\u0940, \\u092a\\u0902\\u0924\\u092a\\u094d\\u0930\\u0927\\u093e\\u0928 \\u0906\\u0923\\u093f \\u0907\\u0924\\u0930 \\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0939\\u0947 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928\\u093e\\u091a\\u0947 \\u0918\\u091f\\u0915 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"How many states are there in India? (Short Answer)\",\"a\":\"28 states.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0938\\u0927\\u094d\\u092f\\u093e \\u090f\\u0915\\u0942\\u0923 \\u0968\\u096e \\u0930\\u093e\\u091c\\u094d\\u092f\\u0947 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"What does the State Government look after? (Long Answer)\",\"a\":\"Education, healthcare, transport and law &amp; order.\",\"e\":\"\\u0930\\u093e\\u091c\\u094d\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923, \\u0906\\u0930\\u094b\\u0917\\u094d\\u092f \\u0938\\u0947\\u0935\\u093e, \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u0906\\u0923\\u093f \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u0924\\u0940\\u0932 \\u0915\\u093e\\u092f\\u0926\\u093e \\u0935 \\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u092f\\u093e\\u0902\\u091a\\u0940 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930\\u0940 \\u0938\\u093e\\u0902\\u092d\\u093e\\u0933\\u0924\\u0947.\"},{\"q\":\"Who is the head of the State Government? (Short Answer)\",\"a\":\"Chief Minister.\",\"e\":\"\\u092e\\u0941\\u0916\\u094d\\u092f\\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0939\\u093e \\u0930\\u093e\\u091c\\u094d\\u092f \\u0936\\u093e\\u0938\\u0928\\u093e\\u091a\\u093e \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0905\\u0938\\u0924\\u094b.\"},{\"q\":\"Who is the constitutional head of a state? (Short Answer)\",\"a\":\"Governor.\",\"e\":\"\\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u093e \\u0918\\u091f\\u0928\\u093e\\u0924\\u094d\\u092e\\u0915 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0930\\u093e\\u091c\\u094d\\u092f\\u092a\\u093e\\u0932 \\u0905\\u0938\\u0924\\u094b.\"},{\"q\":\"How many Union Territories are there in India? (Short Answer)\",\"a\":\"Eight.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u090f\\u0915\\u0942\\u0923 \\u096e \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Who governs the Union Territories? (Short Answer)\",\"a\":\"Central Government.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936\\u093e\\u0902\\u091a\\u0947 \\u0936\\u093e\\u0938\\u0928 \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923\\u092a\\u0923\\u0947 \\u0915\\u093f\\u0902\\u0935\\u093e \\u0905\\u0902\\u0936\\u0924\\u0903 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928\\u093e\\u0915\\u0921\\u0942\\u0928 \\u0915\\u0947\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"What is Local Level Government? (Long Answer)\",\"a\":\"Government for cities, towns and villages.\",\"e\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928 \\u0936\\u0939\\u0930, \\u0928\\u0917\\u0930 \\u0906\\u0923\\u093f \\u0917\\u093e\\u0935\\u093e\\u0902\\u092e\\u0927\\u0940\\u0932 \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0926\\u0948\\u0928\\u0902\\u0926\\u093f\\u0928 \\u0935 \\u092e\\u0942\\u0932\\u092d\\u0942\\u0924 \\u0917\\u0930\\u091c\\u093e \\u091c\\u0938\\u0947 \\u092a\\u093e\\u0923\\u0940\\u092a\\u0941\\u0930\\u0935\\u0920\\u093e, \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u093e, \\u0930\\u0938\\u094d\\u0924\\u0947 \\u0935 \\u0909\\u0926\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092f\\u093e\\u0902\\u091a\\u0940 \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Name the local government body in villages. (Short Answer)\",\"a\":\"Gram Panchayat.\",\"e\":\"\\u0917\\u094d\\u0930\\u093e\\u092e\\u0940\\u0923 \\u092d\\u093e\\u0917\\u093e\\u0924 \\u0917\\u094d\\u0930\\u093e\\u092e\\u092a\\u0902\\u091a\\u093e\\u092f\\u0924 \\u0939\\u0940 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928\\u093e\\u091a\\u0940 \\u092e\\u0941\\u0916\\u094d\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e \\u0905\\u0938\\u0924\\u0947.\"},{\"q\":\"Why is local government important? (Long Answer)\",\"a\":\"It manages daily needs of people.\",\"e\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928 \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0926\\u0948\\u0928\\u0902\\u0926\\u093f\\u0928 \\u0917\\u0930\\u091c\\u093e \\u092a\\u0942\\u0930\\u094d\\u0923 \\u0915\\u0930\\u0924\\u0947. \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928 \\u0925\\u0947\\u091f \\u091c\\u0928\\u0924\\u0947\\u092a\\u0930\\u094d\\u092f\\u0902\\u0924 \\u092a\\u094b\\u0939\\u094b\\u091a\\u0924\\u0947 \\u0935 \\u091c\\u0940\\u0935\\u0928\\u092e\\u093e\\u0928 \\u0938\\u0941\\u0927\\u093e\\u0930\\u0924\\u0947.\"}]','OUR GOVERNMENT','2026-01-14 19:57:01'),(24,78,'OUR GOVERNMENT','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain the meaning of government and describe why it is important for a country.\",\"a\":\"A government is a group of elected members responsible for making decisions and working for the safety, welfare, and development of a country.\",\"e\":\"\\u0938\\u0930\\u0915\\u093e\\u0930 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0926\\u0947\\u0936\\u093e\\u0924\\u0940\\u0932 \\u0932\\u094b\\u0915\\u093e\\u0902\\u0928\\u0940 \\u0928\\u093f\\u0935\\u0921\\u0942\\u0928 \\u0926\\u093f\\u0932\\u0947\\u0932\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940\\u0902\\u091a\\u093e \\u0938\\u092e\\u0942\\u0939 \\u0939\\u094b\\u092f. \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0926\\u0947\\u0936\\u093e\\u0924\\u0940\\u0932 \\u0936\\u093e\\u0902\\u0924\\u0924\\u093e, \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e, \\u0935\\u093f\\u0915\\u093e\\u0938 \\u0906\\u0923\\u093f \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u092e\\u0942\\u0932\\u092d\\u0942\\u0924 \\u0917\\u0930\\u091c\\u093e\\u0902\\u091a\\u0940 \\u092a\\u0942\\u0930\\u094d\\u0924\\u0924\\u093e \\u0915\\u0930\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924 \\u0905\\u0938\\u0924\\u0947.\"},{\"q\":\"Describe the levels at which the government works in India.\",\"a\":\"The government in India works at three levels: Central Government, State Government, and Local Level Government.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0924\\u0940\\u0928 \\u0938\\u094d\\u0924\\u0930\\u093e\\u0902\\u0935\\u0930 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0930\\u0924\\u0947. \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0926\\u0947\\u0936\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924\\u0947, \\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u0915\\u093e\\u0930\\u092d\\u093e\\u0930\\u093e\\u0938\\u093e\\u0920\\u0940 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930 \\u0905\\u0938\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0917\\u093e\\u0935, \\u0936\\u0939\\u0930 \\u0935 \\u0928\\u0917\\u0930\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0917\\u0930\\u091c\\u093e\\u0902\\u091a\\u0940 \\u092a\\u0942\\u0930\\u094d\\u0924\\u0924\\u093e \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Explain the role and functions of the Central Government of India.\",\"a\":\"The Central Government takes decisions for the welfare of the entire country, including defence, foreign trade, and national infrastructure.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u0939\\u093f\\u0924\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924\\u0947. \\u092a\\u0930\\u0926\\u0947\\u0936\\u0940 \\u0906\\u0915\\u094d\\u0930\\u092e\\u0923\\u093e\\u092a\\u093e\\u0938\\u0942\\u0928 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923, \\u092a\\u0930\\u0926\\u0947\\u0936\\u093e\\u0902\\u0936\\u0940 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930, \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0926\\u0932\\u093e\\u0902\\u091a\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e\\u092a\\u0928 \\u0924\\u0938\\u0947\\u091a \\u0930\\u0947\\u0932\\u094d\\u0935\\u0947 \\u0906\\u0923\\u093f \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u092e\\u0939\\u093e\\u092e\\u093e\\u0930\\u094d\\u0917\\u093e\\u0902\\u091a\\u0940 \\u0909\\u092d\\u093e\\u0930\\u0923\\u0940 \\u0939\\u0940 \\u0924\\u094d\\u092f\\u093e\\u091a\\u0940 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0915\\u093e\\u092e\\u0947 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Who are the main members of the Central Government?\",\"a\":\"The President, the Prime Minister, and other ministers are members of the Central Government.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u092a\\u0924\\u0940, \\u092a\\u0902\\u0924\\u092a\\u094d\\u0930\\u0927\\u093e\\u0928 \\u0906\\u0923\\u093f \\u0907\\u0924\\u0930 \\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u092f\\u093e\\u0902\\u091a\\u093e \\u0938\\u092e\\u093e\\u0935\\u0947\\u0936 \\u0905\\u0938\\u0924\\u094b. \\u0939\\u0947 \\u0938\\u0930\\u094d\\u0935\\u091c\\u0923 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928\\u093e\\u0924 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u092d\\u0942\\u092e\\u093f\\u0915\\u093e \\u092c\\u091c\\u093e\\u0935\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain how the State Government is formed and what its responsibilities are.\",\"a\":\"Each state has its own government, elected by the people of the state, and it manages state-level issues like education and healthcare.\",\"e\":\"\\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0938\\u094d\\u0935\\u0924\\u0903\\u091a\\u0947 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0905\\u0938\\u0924\\u0947. \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u0924\\u0940\\u0932 \\u0932\\u094b\\u0915 \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940 \\u0928\\u093f\\u0935\\u0921\\u0924\\u093e\\u0924. \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923, \\u0906\\u0930\\u094b\\u0917\\u094d\\u092f\\u0938\\u0947\\u0935\\u093e, \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0906\\u0923\\u093f \\u0915\\u093e\\u092f\\u0926\\u093e-\\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u092f\\u093e \\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u094d\\u092f\\u093e \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0931\\u094d\\u092f\\u093e \\u0905\\u0938\\u0924\\u093e\\u0924.\"},{\"q\":\"Name the main members of the State Government and explain their roles briefly.\",\"a\":\"The Governor, Chief Minister, and other ministers form the State Government.\",\"e\":\"\\u0930\\u093e\\u091c\\u094d\\u092f\\u092a\\u093e\\u0932, \\u092e\\u0941\\u0916\\u094d\\u092f\\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0906\\u0923\\u093f \\u0907\\u0924\\u0930 \\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0939\\u0947 \\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u0947 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0938\\u0926\\u0938\\u094d\\u092f \\u0905\\u0938\\u0924\\u093e\\u0924. \\u092e\\u0941\\u0916\\u094d\\u092f\\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u0915\\u093e\\u0930\\u092d\\u093e\\u0930\\u093e\\u091a\\u0947 \\u0928\\u0947\\u0924\\u0943\\u0924\\u094d\\u0935 \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"What are Union Territories and how are they governed in India?\",\"a\":\"Union Territories are regions governed partly or fully by the Central Government.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936\\u093e\\u0902\\u0928\\u093e \\u0938\\u0902\\u0918 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936 \\u0905\\u0938\\u0947 \\u092e\\u094d\\u0939\\u0923\\u0924\\u093e\\u0924. \\u0939\\u0947 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936 \\u0905\\u0902\\u0936\\u0924\\u0903 \\u0915\\u093f\\u0902\\u0935\\u093e \\u092a\\u0942\\u0930\\u094d\\u0923\\u092a\\u0923\\u0947 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u0915\\u0947\\u0932\\u0947 \\u091c\\u093e\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the difference between State Governments and Union Territory Governments.\",\"a\":\"States have their own governments, while Union Territories are governed by the Central Government.\",\"e\":\"\\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u0938\\u094d\\u0935\\u0924\\u0903\\u091a\\u0947 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0905\\u0938\\u0924\\u0947, \\u0924\\u0930 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936\\u093e\\u0902\\u0935\\u0930 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u093e \\u0925\\u0947\\u091f \\u0915\\u093f\\u0902\\u0935\\u093e \\u0905\\u0902\\u0936\\u0924\\u0903 \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 \\u0905\\u0938\\u0924\\u0947.\"},{\"q\":\"What is Local Level Government and why is it important?\",\"a\":\"Local Level Government looks after the needs of villages, towns, and cities.\",\"e\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0917\\u093e\\u0935, \\u0936\\u0939\\u0930 \\u0906\\u0923\\u093f \\u0928\\u0917\\u0930\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0926\\u0948\\u0928\\u0902\\u0926\\u093f\\u0928 \\u0917\\u0930\\u091c\\u093e\\u0902\\u091a\\u0940 \\u0915\\u093e\\u0933\\u091c\\u0940 \\u0918\\u0947\\u0924\\u0947. \\u092a\\u093e\\u0923\\u0940\\u092a\\u0941\\u0930\\u0935\\u0920\\u093e, \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u093e, \\u0930\\u0938\\u094d\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0909\\u0926\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0939\\u0947 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u0906\\u0939\\u0947.\"},{\"q\":\"Name the local government bodies in urban areas.\",\"a\":\"Municipal Corporations and Municipal Committees are local government bodies in cities and towns.\",\"e\":\"\\u092e\\u0939\\u093e\\u0928\\u0917\\u0930\\u092a\\u093e\\u0932\\u093f\\u0915\\u093e \\u0906\\u0923\\u093f \\u0928\\u0917\\u0930\\u092a\\u093e\\u0932\\u093f\\u0915\\u093e \\u092f\\u093e \\u0936\\u0939\\u0930\\u0940 \\u092d\\u093e\\u0917\\u093e\\u0924\\u0940\\u0932 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0938\\u094d\\u0935\\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e \\u0906\\u0939\\u0947\\u0924. \\u0924\\u094d\\u092f\\u093e \\u0936\\u0939\\u0930\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the local government system in rural areas.\",\"a\":\"In villages, local governance is managed by the Gram Panchayat.\",\"e\":\"\\u0917\\u094d\\u0930\\u093e\\u092e\\u0940\\u0923 \\u092d\\u093e\\u0917\\u093e\\u0924 \\u0917\\u094d\\u0930\\u093e\\u092e\\u092a\\u0902\\u091a\\u093e\\u092f\\u0924 \\u0939\\u0940 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0938\\u094d\\u0935\\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e \\u0905\\u0938\\u0924\\u0947. \\u0924\\u0940 \\u0917\\u093e\\u0935\\u093e\\u0924\\u0940\\u0932 \\u0935\\u093f\\u0915\\u093e\\u0938\\u0915\\u093e\\u092e\\u0947 \\u0906\\u0923\\u093f \\u0928\\u093e\\u0917\\u0930\\u093f\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0917\\u0930\\u091c\\u093e \\u092a\\u0942\\u0930\\u094d\\u0923 \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Why are elections important in a democracy?\",\"a\":\"Elections allow people to choose their representatives and form a government.\",\"e\":\"\\u0928\\u093f\\u0935\\u0921\\u0923\\u0941\\u0915\\u093e \\u0932\\u094b\\u0915\\u0936\\u093e\\u0939\\u0940\\u0924\\u0940\\u0932 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u093e \\u092d\\u093e\\u0917 \\u0906\\u0939\\u0947\\u0924. \\u0924\\u094d\\u092f\\u093e\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u0932\\u094b\\u0915 \\u0906\\u092a\\u0932\\u094d\\u092f\\u093e \\u092a\\u0938\\u0902\\u0924\\u0940\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940 \\u0928\\u093f\\u0935\\u0921\\u0924\\u093e\\u0924 \\u0906\\u0923\\u093f \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0938\\u094d\\u0925\\u093e\\u092a\\u0928 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain how government works for the welfare of the people.\",\"a\":\"The government ensures safety, development, and basic facilities for citizens.\",\"e\":\"\\u0938\\u0930\\u0915\\u093e\\u0930 \\u0928\\u093e\\u0917\\u0930\\u093f\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924\\u0924\\u0947\\u0938\\u093e\\u0920\\u0940, \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0906\\u0923\\u093f \\u092e\\u0942\\u0932\\u092d\\u0942\\u0924 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0915\\u0930\\u0942\\u0928 \\u0926\\u0947\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Describe the role of government in maintaining law and order.\",\"a\":\"The government makes laws and ensures they are followed to maintain peace.\",\"e\":\"\\u0915\\u093e\\u092f\\u0926\\u093e \\u0906\\u0923\\u093f \\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u0930\\u093e\\u0916\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0915\\u093e\\u092f\\u0926\\u0947 \\u092c\\u0928\\u0935\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0924\\u094d\\u092f\\u093e\\u0902\\u091a\\u0940 \\u0905\\u0902\\u092e\\u0932\\u092c\\u091c\\u093e\\u0935\\u0923\\u0940 \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Summarise the importance of having different levels of government in India.\",\"a\":\"Different levels of government ensure effective administration from national to local level.\",\"e\":\"\\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u0947 \\u0935\\u093f\\u0935\\u093f\\u0927 \\u0938\\u094d\\u0924\\u0930 \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0926\\u0947\\u0936\\u092a\\u093e\\u0924\\u0933\\u0940\\u092a\\u093e\\u0938\\u0942\\u0928 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u092a\\u093e\\u0924\\u0933\\u0940\\u092a\\u0930\\u094d\\u092f\\u0902\\u0924 \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928 \\u092a\\u094d\\u0930\\u092d\\u093e\\u0935\\u0940\\u092a\\u0923\\u0947 \\u0930\\u093e\\u092c\\u0935\\u0924\\u093e \\u092f\\u0947\\u0924\\u0947.\"}]','OUR GOVERNMENT','2026-01-16 17:24:13'),(25,79,'NATIONAL SYMBOLS','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain why a country needs national symbols and what they represent.\",\"a\":\"A country needs national symbols to express its identity, values, culture, and unity.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939\\u0947 \\u0926\\u0947\\u0936\\u093e\\u091a\\u0940 \\u0913\\u0933\\u0916 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0924\\u093e\\u0924. \\u0924\\u0940 \\u0926\\u0947\\u0936\\u093e\\u091a\\u0940 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940, \\u092e\\u0942\\u0932\\u094d\\u092f\\u0947, \\u090f\\u0915\\u0924\\u093e \\u0906\\u0923\\u093f \\u0905\\u092d\\u093f\\u092e\\u093e\\u0928 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924 \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe the national flag of India and explain the meaning of its colours.\",\"a\":\"The national flag of India has three horizontal colours that symbolise strength, peace, and growth.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u094d\\u092f\\u093e \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0927\\u094d\\u0935\\u091c\\u093e\\u0924 \\u0915\\u0947\\u0936\\u0930\\u0940, \\u092a\\u093e\\u0902\\u0922\\u0930\\u093e \\u0935 \\u0939\\u093f\\u0930\\u0935\\u093e \\u0930\\u0902\\u0917 \\u0906\\u0939\\u0947\\u0924. \\u0915\\u0947\\u0936\\u0930\\u0940 \\u0927\\u0948\\u0930\\u094d\\u092f, \\u092a\\u093e\\u0902\\u0922\\u0930\\u093e \\u0936\\u093e\\u0902\\u0924\\u0924\\u093e \\u0935 \\u0938\\u0924\\u094d\\u092f, \\u0924\\u0930 \\u0939\\u093f\\u0930\\u0935\\u093e \\u0935\\u093f\\u0915\\u093e\\u0938 \\u0935 \\u0938\\u092e\\u0943\\u0926\\u094d\\u0927\\u0940 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0924\\u094b.\"},{\"q\":\"Explain the importance of the Ashoka Chakra in the national flag.\",\"a\":\"The Ashoka Chakra symbolises motion, progress, and righteousness.\",\"e\":\"\\u0905\\u0936\\u094b\\u0915 \\u091a\\u0915\\u094d\\u0930 \\u092a\\u094d\\u0930\\u0917\\u0924\\u0940, \\u0917\\u0924\\u093f\\u092e\\u093e\\u0928\\u0924\\u093e \\u0906\\u0923\\u093f \\u0927\\u0930\\u094d\\u092e\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947. \\u0924\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u091a\\u094b\\u0935\\u0940\\u0938 \\u0906\\u0931\\u094d\\u092f\\u093e \\u0938\\u0924\\u0924 \\u092a\\u0941\\u0922\\u0947 \\u091c\\u093e\\u0923\\u094d\\u092f\\u093e\\u091a\\u093e \\u0938\\u0902\\u0926\\u0947\\u0936 \\u0926\\u0947\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the rules that must be followed while hoisting the national flag.\",\"a\":\"The flag should be respected, never allowed to touch the ground, and hoisted properly.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0927\\u094d\\u0935\\u091c\\u093e\\u091a\\u093e \\u0938\\u0928\\u094d\\u092e\\u093e\\u0928 \\u0930\\u093e\\u0916\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u094b \\u091c\\u092e\\u093f\\u0928\\u0940\\u0932\\u093e \\u0932\\u093e\\u0917\\u0942 \\u0926\\u0947\\u090a \\u0928\\u092f\\u0947, \\u092b\\u093e\\u091f\\u0932\\u0947\\u0932\\u093e \\u0915\\u093f\\u0902\\u0935\\u093e \\u092e\\u0933\\u0932\\u0947\\u0932\\u093e \\u0927\\u094d\\u0935\\u091c \\u0935\\u093e\\u092a\\u0930\\u0942 \\u0928\\u092f\\u0947.\"},{\"q\":\"Describe the national emblem of India and its importance.\",\"a\":\"The national emblem is the official seal of India used by the Government.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939 \\u0939\\u0947 \\u092d\\u093e\\u0930\\u0924 \\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u0947 \\u0905\\u0927\\u093f\\u0915\\u0943\\u0924 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0905\\u0938\\u0942\\u0928 \\u0924\\u0947 \\u0936\\u093e\\u0938\\u0915\\u0940\\u092f \\u0915\\u093e\\u0917\\u0926\\u092a\\u0924\\u094d\\u0930\\u0947 \\u0935 \\u091a\\u0932\\u0928\\u093e\\u0935\\u0930 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Explain the features of the Indian national emblem.\",\"a\":\"It is adapted from the Lion Capital of Ashoka and includes the motto &#039;Satyameva Jayate&#039;.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939 \\u0905\\u0936\\u094b\\u0915 \\u0938\\u094d\\u0924\\u0902\\u092d\\u093e\\u091a\\u094d\\u092f\\u093e \\u0938\\u093f\\u0902\\u0939\\u092e\\u0941\\u0916\\u093e\\u0935\\u0930 \\u0906\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0906\\u0939\\u0947 \\u0906\\u0923\\u093f \\u0924\\u094d\\u092f\\u093e\\u0935\\u0930 \\u2018\\u0938\\u0924\\u094d\\u092f\\u092e\\u0947\\u0935 \\u091c\\u092f\\u0924\\u0947\\u2019 \\u0939\\u093e \\u092c\\u094b\\u0927\\u0935\\u093e\\u0915\\u094d\\u092f \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain the meaning of the motto &#039;Satyameva Jayate&#039;.\",\"a\":\"&#039;Satyameva Jayate&#039; means truth alone triumphs.\",\"e\":\"\\u2018\\u0938\\u0924\\u094d\\u092f\\u092e\\u0947\\u0935 \\u091c\\u092f\\u0924\\u0947\\u2019 \\u092f\\u093e\\u091a\\u093e \\u0905\\u0930\\u094d\\u0925 \\u0938\\u0924\\u094d\\u092f\\u093e\\u091a\\u093e \\u0928\\u0947\\u0939\\u092e\\u0940 \\u0935\\u093f\\u091c\\u092f \\u0939\\u094b\\u0924\\u094b \\u0905\\u0938\\u093e \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe the national anthem of India.\",\"a\":\"&#039;Jana Gana Mana&#039; is the national anthem that praises the nation.\",\"e\":\"\\u2018\\u091c\\u0928 \\u0917\\u0923 \\u092e\\u0928\\u2019 \\u0939\\u0947 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0947 \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0917\\u0940\\u0924 \\u0905\\u0938\\u0942\\u0928 \\u0924\\u0947 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u0917\\u094c\\u0930\\u0935\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain the discipline required during the national anthem.\",\"a\":\"People must stand at attention and show respect during the anthem.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0917\\u0940\\u0924 \\u0938\\u0941\\u0930\\u0942 \\u0905\\u0938\\u0924\\u093e\\u0928\\u093e \\u0938\\u093e\\u0935\\u0927\\u093e\\u0928 \\u0938\\u094d\\u0925\\u093f\\u0924\\u0940\\u0924 \\u0909\\u092d\\u0947 \\u0930\\u093e\\u0939\\u0942\\u0928 \\u0906\\u0926\\u0930 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0923\\u0947 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe the national song of India and its role in history.\",\"a\":\"&#039;Vande Mataram&#039; inspired freedom fighters during the independence movement.\",\"e\":\"\\u2018\\u0935\\u0902\\u0926\\u0947 \\u092e\\u093e\\u0924\\u0930\\u092e\\u094d\\u2019 \\u092f\\u093e \\u0917\\u0940\\u0924\\u093e\\u0928\\u0947 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0932\\u0922\\u094d\\u092f\\u093e\\u0924 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0938\\u0948\\u0928\\u093f\\u0915\\u093e\\u0902\\u0928\\u093e \\u092a\\u094d\\u0930\\u0947\\u0930\\u0923\\u093e \\u0926\\u093f\\u0932\\u0940.\"},{\"q\":\"Explain why the Royal Bengal Tiger is the national animal of India.\",\"a\":\"It represents strength, courage, and India&#039;s rich wildlife.\",\"e\":\"\\u0930\\u0949\\u092f\\u0932 \\u092c\\u0902\\u0917\\u093e\\u0932 \\u0935\\u093e\\u0918 \\u0936\\u0915\\u094d\\u0924\\u0940, \\u0927\\u0948\\u0930\\u094d\\u092f \\u0906\\u0923\\u093f \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u094d\\u092f\\u093e \\u0935\\u0928\\u094d\\u092f\\u091c\\u0940\\u0935\\u0928\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe the national bird of India.\",\"a\":\"The peacock is the national bird and symbolises beauty and grace.\",\"e\":\"\\u092e\\u094b\\u0930 \\u0939\\u093e \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u093e \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u092a\\u0915\\u094d\\u0937\\u0940 \\u0905\\u0938\\u0942\\u0928 \\u0924\\u094b \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f \\u0935 \\u0938\\u0941\\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0924\\u0947\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain the significance of the national flower of India.\",\"a\":\"The lotus symbolises purity, knowledge, and beauty.\",\"e\":\"\\u0915\\u092e\\u0933 \\u0939\\u0947 \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u092b\\u0942\\u0932 \\u0905\\u0938\\u0942\\u0928 \\u0924\\u0947 \\u092a\\u0935\\u093f\\u0924\\u094d\\u0930\\u0924\\u093e, \\u091c\\u094d\\u091e\\u093e\\u0928 \\u0906\\u0923\\u093f \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain how national symbols unite citizens.\",\"a\":\"They create a sense of unity and national pride.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939\\u0947 \\u0928\\u093e\\u0917\\u0930\\u093f\\u0915\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u090f\\u0915\\u0924\\u093e \\u0906\\u0923\\u093f \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u093e\\u092d\\u093f\\u092e\\u093e\\u0928\\u093e\\u091a\\u0940 \\u092d\\u093e\\u0935\\u0928\\u093e \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"Summarise why respecting national symbols is important.\",\"a\":\"Respecting national symbols shows responsibility and love for the nation.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939\\u093e\\u0902\\u091a\\u093e \\u0938\\u0928\\u094d\\u092e\\u093e\\u0928 \\u0915\\u0930\\u0923\\u0947 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0926\\u0947\\u0936\\u093e\\u092c\\u0926\\u094d\\u0926\\u0932 \\u092a\\u094d\\u0930\\u0947\\u092e \\u0935 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930\\u0940 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0923\\u0947 \\u0939\\u094b\\u092f.\"}]','NATIONAL SYMBOLS','2026-01-16 17:32:19'),(26,80,'OUR GREAT LEADERS','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Describe the early life and education of Mahatma Gandhi.\",\"a\":\"Mahatma Gandhi was born on 2 October 1869 at Porbandar in Gujarat. He studied law in England and later worked as a lawyer.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940 \\u092f\\u093e\\u0902\\u091a\\u093e \\u091c\\u0928\\u094d\\u092e \\u0968 \\u0911\\u0915\\u094d\\u091f\\u094b\\u092c\\u0930 \\u0967\\u096e\\u096c\\u096f \\u0930\\u094b\\u091c\\u0940 \\u0917\\u0941\\u091c\\u0930\\u093e\\u0924\\u092e\\u0927\\u0940\\u0932 \\u092a\\u094b\\u0930\\u092c\\u0902\\u0926\\u0930 \\u092f\\u0947\\u0925\\u0947 \\u091d\\u093e\\u0932\\u093e. \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u0940 \\u0907\\u0902\\u0917\\u094d\\u0932\\u0902\\u0921\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0915\\u093e\\u092f\\u0926\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923 \\u0918\\u0947\\u0924\\u0932\\u0947 \\u0906\\u0923\\u093f \\u0935\\u0915\\u0940\\u0932 \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0915\\u093e\\u092e \\u0915\\u0947\\u0932\\u0947.\"},{\"q\":\"Explain the role of Mahatma Gandhi in India\\u2019s freedom struggle.\",\"a\":\"Mahatma Gandhi led the freedom struggle using the principles of truth, non-violence, and non-cooperation.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940\\u0902\\u0928\\u0940 \\u0938\\u0924\\u094d\\u092f, \\u0905\\u0939\\u093f\\u0902\\u0938\\u093e \\u0906\\u0923\\u093f \\u0905\\u0938\\u0939\\u0915\\u093e\\u0930 \\u092f\\u093e \\u0924\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u0902\\u0935\\u0930 \\u0906\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0932\\u0922\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0928\\u0947\\u0924\\u0943\\u0924\\u094d\\u0935 \\u0915\\u0947\\u0932\\u0947.\"},{\"q\":\"Describe the concept of Satyagraha and its importance.\",\"a\":\"Satyagraha was a method of non-violent protest used by Mahatma Gandhi to fight injustice.\",\"e\":\"\\u0938\\u0924\\u094d\\u092f\\u093e\\u0917\\u094d\\u0930\\u0939 \\u0939\\u0940 \\u0905\\u0928\\u094d\\u092f\\u093e\\u092f\\u093e\\u0935\\u093f\\u0930\\u0941\\u0926\\u094d\\u0927 \\u0905\\u0939\\u093f\\u0902\\u0938\\u0915 \\u092e\\u093e\\u0930\\u094d\\u0917\\u093e\\u0928\\u0947 \\u0932\\u0922\\u0923\\u094d\\u092f\\u093e\\u091a\\u0940 \\u092a\\u0926\\u094d\\u0927\\u0924 \\u0939\\u094b\\u0924\\u0940. \\u092f\\u093e \\u091a\\u0933\\u0935\\u0933\\u0940\\u092e\\u0941\\u0933\\u0947 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u0932\\u094b\\u0915 \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u0938\\u0902\\u0916\\u094d\\u092f\\u0947\\u0928\\u0947 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0932\\u0922\\u094d\\u092f\\u093e\\u0924 \\u0938\\u0939\\u092d\\u093e\\u0917\\u0940 \\u091d\\u093e\\u0932\\u0947.\"},{\"q\":\"Explain why Mahatma Gandhi was given the title \\u2018Mahatma\\u2019.\",\"a\":\"The title \\u2018Mahatma\\u2019 was given to Gandhi for his simplicity, moral values, and dedication to the nation.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940\\u0902\\u091a\\u0940 \\u0938\\u093e\\u0927\\u0940 \\u091c\\u0940\\u0935\\u0928\\u0936\\u0948\\u0932\\u0940, \\u0909\\u091a\\u094d\\u091a \\u0928\\u0948\\u0924\\u093f\\u0915 \\u092e\\u0942\\u0932\\u094d\\u092f\\u0947 \\u0906\\u0923\\u093f \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u093e\\u0938\\u093e\\u0920\\u0940\\u091a\\u0947 \\u092f\\u094b\\u0917\\u0926\\u093e\\u0928 \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u2018\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e\\u2019 \\u0939\\u0940 \\u092a\\u0926\\u0935\\u0940 \\u0926\\u0947\\u0923\\u094d\\u092f\\u093e\\u0924 \\u0906\\u0932\\u0940.\"},{\"q\":\"Describe the early life of Pandit Jawaharlal Nehru.\",\"a\":\"Pandit Jawaharlal Nehru was born on 14 November 1889 in Allahabad and studied law.\",\"e\":\"\\u092a\\u0902\\u0921\\u093f\\u0924 \\u091c\\u0935\\u093e\\u0939\\u0930\\u0932\\u093e\\u0932 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u092f\\u093e\\u0902\\u091a\\u093e \\u091c\\u0928\\u094d\\u092e \\u0967\\u096a \\u0928\\u094b\\u0935\\u094d\\u0939\\u0947\\u0902\\u092c\\u0930 \\u0967\\u096e\\u096e\\u096f \\u0930\\u094b\\u091c\\u0940 \\u0905\\u0932\\u093e\\u0939\\u093e\\u092c\\u093e\\u0926 (\\u092a\\u094d\\u0930\\u092f\\u093e\\u0917\\u0930\\u093e\\u091c) \\u092f\\u0947\\u0925\\u0947 \\u091d\\u093e\\u0932\\u093e. \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u0940 \\u0915\\u093e\\u092f\\u0926\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923 \\u0918\\u0947\\u0924\\u0932\\u0947.\"},{\"q\":\"Explain the contribution of Jawaharlal Nehru to independent India.\",\"a\":\"Jawaharlal Nehru became the first Prime Minister of independent India and worked for nation-building.\",\"e\":\"\\u0938\\u094d\\u0935\\u0924\\u0902\\u0924\\u094d\\u0930 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0947 \\u092a\\u0939\\u093f\\u0932\\u0947 \\u092a\\u0902\\u0924\\u092a\\u094d\\u0930\\u0927\\u093e\\u0928 \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u092a\\u0902\\u0921\\u093f\\u0924 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u092f\\u093e\\u0902\\u0928\\u0940 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0906\\u0923\\u093f \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923\\u093e\\u0938\\u093e\\u0920\\u0940 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0947\\u0932\\u0947.\"},{\"q\":\"Why is Jawaharlal Nehru remembered as \\u2018Chacha Nehru\\u2019?\",\"a\":\"He loved children deeply, and children affectionately called him \\u2018Chacha Nehru\\u2019.\",\"e\":\"\\u092a\\u0902\\u0921\\u093f\\u0924 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u092e\\u0941\\u0932\\u093e\\u0902\\u0935\\u0930 \\u0916\\u0942\\u092a \\u092a\\u094d\\u0930\\u0947\\u092e \\u0915\\u0930\\u0924 \\u0905\\u0938\\u0924, \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092e\\u0941\\u0932\\u0947 \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u092a\\u094d\\u0930\\u0947\\u092e\\u093e\\u0928\\u0947 \\u2018\\u091a\\u093e\\u091a\\u093e \\u0928\\u0947\\u0939\\u0930\\u0942\\u2019 \\u092e\\u094d\\u0939\\u0923\\u0924.\"},{\"q\":\"Explain the significance of Children\\u2019s Day in India.\",\"a\":\"Children\\u2019s Day is celebrated on Jawaharlal Nehru\\u2019s birthday to honour his love for children.\",\"e\":\"\\u092a\\u0902\\u0921\\u093f\\u0924 \\u0928\\u0947\\u0939\\u0930\\u0942\\u0902\\u091a\\u094d\\u092f\\u093e \\u091c\\u0928\\u094d\\u092e\\u0926\\u093f\\u0928\\u0940 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947\\u091a \\u0967\\u096a \\u0928\\u094b\\u0935\\u094d\\u0939\\u0947\\u0902\\u092c\\u0930 \\u0930\\u094b\\u091c\\u0940 \\u092c\\u093e\\u0932\\u0926\\u093f\\u0928 \\u0938\\u093e\\u091c\\u0930\\u093e \\u0915\\u0947\\u0932\\u093e \\u091c\\u093e\\u0924\\u094b, \\u0915\\u093e\\u0930\\u0923 \\u0924\\u094d\\u092f\\u093e\\u0902\\u091a\\u0947 \\u092e\\u0941\\u0932\\u093e\\u0902\\u0935\\u0930\\u0940\\u0932 \\u092a\\u094d\\u0930\\u0947\\u092e \\u092a\\u094d\\u0930\\u0938\\u093f\\u0926\\u094d\\u0927 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe the early life and education of Sardar Vallabhbhai Patel.\",\"a\":\"Sardar Vallabhbhai Patel was born on 31 October 1875 in Nadiad and later became a lawyer.\",\"e\":\"\\u0938\\u0930\\u0926\\u093e\\u0930 \\u0935\\u0932\\u094d\\u0932\\u092d\\u092d\\u093e\\u0908 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u091a\\u093e \\u091c\\u0928\\u094d\\u092e \\u0969\\u0967 \\u0911\\u0915\\u094d\\u091f\\u094b\\u092c\\u0930 \\u0967\\u096e\\u096d\\u096b \\u0930\\u094b\\u091c\\u0940 \\u0917\\u0941\\u091c\\u0930\\u093e\\u0924\\u092e\\u0927\\u0940\\u0932 \\u0928\\u0921\\u093f\\u092f\\u093e\\u0926 \\u092f\\u0947\\u0925\\u0947 \\u091d\\u093e\\u0932\\u093e. \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u0940 \\u0915\\u093e\\u092f\\u0926\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923 \\u0918\\u0947\\u0924\\u0932\\u0947.\"},{\"q\":\"Explain the role of Sardar Vallabhbhai Patel in India\\u2019s freedom movement.\",\"a\":\"Sardar Patel actively participated in the freedom struggle inspired by Gandhi\\u2019s Satyagraha.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940\\u0902\\u091a\\u094d\\u092f\\u093e \\u0938\\u0924\\u094d\\u092f\\u093e\\u0917\\u094d\\u0930\\u0939\\u093e\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0947\\u0930\\u093f\\u0924 \\u0939\\u094b\\u090a\\u0928 \\u0938\\u0930\\u0926\\u093e\\u0930 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u0928\\u0940 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0932\\u0922\\u094d\\u092f\\u093e\\u0924 \\u0938\\u0915\\u094d\\u0930\\u093f\\u092f \\u0938\\u0939\\u092d\\u093e\\u0917 \\u0918\\u0947\\u0924\\u0932\\u093e.\"},{\"q\":\"Why is Sardar Vallabhbhai Patel known as the \\u2018Iron Man of India\\u2019?\",\"a\":\"He played a key role in uniting the princely states of India into one nation.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0940 \\u0938\\u0930\\u094d\\u0935 \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e\\u0928\\u0947 \\u090f\\u0915\\u0924\\u094d\\u0930 \\u0906\\u0923\\u0942\\u0928 \\u090f\\u0915\\u0938\\u0902\\u0918 \\u0926\\u0947\\u0936 \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0915\\u0930\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u0940 \\u092e\\u094b\\u0932\\u093e\\u091a\\u0940 \\u092d\\u0942\\u092e\\u093f\\u0915\\u093e \\u092c\\u091c\\u093e\\u0935\\u0932\\u0940, \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u2018\\u0932\\u094c\\u0939\\u092a\\u0941\\u0930\\u0941\\u0937\\u2019 \\u092e\\u094d\\u0939\\u091f\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Describe the political positions held by Sardar Vallabhbhai Patel after independence.\",\"a\":\"He became the first Deputy Prime Minister and Home Minister of independent India.\",\"e\":\"\\u0938\\u094d\\u0935\\u0924\\u0902\\u0924\\u094d\\u0930 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0947 \\u092a\\u0939\\u093f\\u0932\\u0947 \\u0909\\u092a\\u092a\\u0902\\u0924\\u092a\\u094d\\u0930\\u0927\\u093e\\u0928 \\u0906\\u0923\\u093f \\u0917\\u0943\\u0939\\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0938\\u0930\\u0926\\u093e\\u0930 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u0928\\u0940 \\u0915\\u093e\\u092e \\u0915\\u0947\\u0932\\u0947.\"},{\"q\":\"Explain the importance of the Statue of Unity.\",\"a\":\"The Statue of Unity was built to honour Sardar Vallabhbhai Patel and his contribution to India.\",\"e\":\"\\u0938\\u0930\\u0926\\u093e\\u0930 \\u0935\\u0932\\u094d\\u0932\\u092d\\u092d\\u093e\\u0908 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0915\\u093e\\u0930\\u094d\\u092f\\u093e\\u091a\\u093e \\u0917\\u094c\\u0930\\u0935 \\u0915\\u0930\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0917\\u0941\\u091c\\u0930\\u093e\\u0924\\u092e\\u0927\\u0940\\u0932 \\u0915\\u0947\\u0935\\u0921\\u093f\\u092f\\u093e \\u092f\\u0947\\u0925\\u0947 \\u2018\\u0938\\u094d\\u091f\\u0945\\u091a\\u094d\\u092f\\u0942 \\u0911\\u092b \\u092f\\u0941\\u0928\\u093f\\u091f\\u0940\\u2019 \\u0909\\u092d\\u093e\\u0930\\u0923\\u094d\\u092f\\u093e\\u0924 \\u0906\\u0932\\u0940 \\u0906\\u0939\\u0947.\"},{\"q\":\"How did the ideals of Mahatma Gandhi influence other national leaders?\",\"a\":\"Gandhi\\u2019s principles inspired leaders like Nehru and Patel to serve the nation selflessly.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940\\u0902\\u091a\\u094d\\u092f\\u093e \\u0935\\u093f\\u091a\\u093e\\u0930\\u093e\\u0902\\u0928\\u0940 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u0906\\u0923\\u093f \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u0938\\u093e\\u0930\\u0916\\u094d\\u092f\\u093e \\u0928\\u0947\\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u0926\\u0947\\u0936\\u0938\\u0947\\u0935\\u0947\\u0938\\u093e\\u0920\\u0940 \\u092a\\u094d\\u0930\\u0947\\u0930\\u0923\\u093e \\u0926\\u093f\\u0932\\u0940.\"},{\"q\":\"Summarise the collective contribution of these great leaders to India.\",\"a\":\"Gandhi, Nehru, and Patel contributed immensely to India\\u2019s freedom, unity, and development.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940, \\u092a\\u0902\\u0921\\u093f\\u0924 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u0906\\u0923\\u093f \\u0938\\u0930\\u0926\\u093e\\u0930 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u0928\\u0940 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u094d\\u092f\\u093e \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f, \\u090f\\u0915\\u0924\\u093e \\u0906\\u0923\\u093f \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0905\\u092e\\u0942\\u0932\\u094d\\u092f \\u092f\\u094b\\u0917\\u0926\\u093e\\u0928 \\u0926\\u093f\\u0932\\u0947.\"}]','OUR GREAT LEADERS','2026-01-16 17:34:50'),(27,81,'TRANSPORT AND COMMUNICATION','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain what is meant by means of transport and why they are important in daily life.\",\"a\":\"Means of transport are vehicles used to travel from one place to another and they help people and goods move easily.\",\"e\":\"\\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u091a\\u0940 \\u0938\\u093e\\u0927\\u0928\\u0947 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u090f\\u0915\\u093e \\u0920\\u093f\\u0915\\u093e\\u0923\\u093e\\u0939\\u0942\\u0928 \\u0926\\u0941\\u0938\\u0931\\u094d\\u092f\\u093e \\u0920\\u093f\\u0915\\u093e\\u0923\\u0940 \\u091c\\u093e\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0940 \\u091c\\u093e\\u0923\\u093e\\u0930\\u0940 \\u0935\\u093e\\u0939\\u0928\\u0947 \\u0939\\u094b\\u0924. \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u0940 \\u0935 \\u0935\\u0938\\u094d\\u0924\\u0942\\u0902\\u091a\\u0940 \\u0939\\u093e\\u0932\\u091a\\u093e\\u0932 \\u0938\\u0941\\u0932\\u092d \\u0915\\u0930\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0939\\u0940 \\u0938\\u093e\\u0927\\u0928\\u0947 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Describe land transport and explain its different forms.\",\"a\":\"Land transport includes vehicles that move on land and has two forms: road transport and rail transport.\",\"e\":\"\\u092d\\u0942\\u092e\\u0940 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u091c\\u092e\\u093f\\u0928\\u0940\\u0935\\u0930 \\u091a\\u093e\\u0932\\u0923\\u093e\\u0930\\u0940 \\u0935\\u093e\\u0939\\u0928\\u0947. \\u0930\\u0938\\u094d\\u0924\\u0947 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0935 \\u0930\\u0947\\u0932\\u094d\\u0935\\u0947 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0939\\u0947 \\u092d\\u0942\\u092e\\u0940 \\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u091a\\u0947 \\u0926\\u094b\\u0928 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Explain the importance of road transport in daily life.\",\"a\":\"Road transport is commonly used for short distances and for carrying people and goods within cities and villages.\",\"e\":\"\\u0930\\u0938\\u094d\\u0924\\u0947 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0939\\u0940 \\u0926\\u0948\\u0928\\u0902\\u0926\\u093f\\u0928 \\u091c\\u0940\\u0935\\u0928\\u093e\\u0924 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0927\\u093f\\u0915 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0940 \\u091c\\u093e\\u0923\\u093e\\u0930\\u0940 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0906\\u0939\\u0947. \\u0905\\u0932\\u094d\\u092a \\u0905\\u0902\\u0924\\u0930\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u0938\\u0947\\u091a \\u0917\\u093e\\u0935\\u0947 \\u0935 \\u0936\\u0939\\u0930\\u093e\\u0902\\u0924 \\u0938\\u093e\\u092e\\u093e\\u0928 \\u0935 \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u0938\\u093e\\u0920\\u0940 \\u0924\\u0940 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe the role of rail transport in a country.\",\"a\":\"Rail transport is used to travel long distances and to transport goods across different regions.\",\"e\":\"\\u0930\\u0947\\u0932\\u094d\\u0935\\u0947 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0932\\u093e\\u0902\\u092c \\u0905\\u0902\\u0924\\u0930\\u093e\\u091a\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0935\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u0938\\u0947\\u091a \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u092e\\u093e\\u0923\\u093e\\u0935\\u0930 \\u092e\\u093e\\u0932\\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u0938\\u093e\\u0920\\u0940 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0940 \\u0920\\u0930\\u0924\\u0947.\"},{\"q\":\"Explain why land transport is considered the cheapest means of transport.\",\"a\":\"Land transport requires less cost compared to air and water transport and is easily available.\",\"e\":\"\\u0907\\u0924\\u0930 \\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u091a\\u094d\\u092f\\u093e \\u0938\\u093e\\u0927\\u0928\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0924\\u0941\\u0932\\u0928\\u0947\\u0924 \\u092d\\u0942\\u092e\\u0940 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0915\\u092e\\u0940 \\u0916\\u0930\\u094d\\u091a\\u093f\\u0915 \\u0935 \\u0938\\u0930\\u094d\\u0935\\u0938\\u0941\\u0932\\u092d \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u0940 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u0938\\u094d\\u0935\\u0938\\u094d\\u0924 \\u092e\\u093e\\u0928\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Describe water transport and its uses.\",\"a\":\"Water transport includes boats, ships, and steamers used for travelling and carrying goods over water.\",\"e\":\"\\u092a\\u093e\\u0923\\u094d\\u092f\\u093e\\u0935\\u0930\\u0942\\u0928 \\u092a\\u094d\\u0930\\u0935\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0935 \\u092e\\u093e\\u0932\\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u0938\\u093e\\u0920\\u0940 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0940 \\u091c\\u093e\\u0923\\u093e\\u0930\\u0940 \\u0935\\u093e\\u0939\\u0928\\u0947 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u091c\\u0932\\u0935\\u093e\\u0939\\u0924\\u0942\\u0915. \\u0928\\u094c\\u0915\\u093e, \\u091c\\u0939\\u093e\\u091c\\u0947 \\u0935 \\u0938\\u094d\\u091f\\u0940\\u092e\\u0930 \\u0939\\u0940 \\u0924\\u094d\\u092f\\u093e\\u091a\\u0940 \\u0909\\u0926\\u093e\\u0939\\u0930\\u0923\\u0947 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Explain the importance of water transport in international trade.\",\"a\":\"Water transport allows heavy goods to be carried over long distances between countries.\",\"e\":\"\\u091c\\u0932\\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u092e\\u0941\\u0933\\u0947 \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u092e\\u093e\\u0923\\u093e\\u0924 \\u0935 \\u091c\\u0921 \\u092e\\u093e\\u0932 \\u090f\\u0915\\u093e \\u0926\\u0947\\u0936\\u093e\\u0924\\u0942\\u0928 \\u0926\\u0941\\u0938\\u0931\\u094d\\u092f\\u093e \\u0926\\u0947\\u0936\\u093e\\u0924 \\u0915\\u092e\\u0940 \\u0916\\u0930\\u094d\\u091a\\u093e\\u0924 \\u0928\\u0947\\u0932\\u093e \\u091c\\u093e\\u090a \\u0936\\u0915\\u0924\\u094b, \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0906\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930 \\u0938\\u0941\\u0932\\u092d \\u0939\\u094b\\u0924\\u094b.\"},{\"q\":\"Describe air transport and explain why it is fast.\",\"a\":\"Air transport uses aeroplanes and helicopters and is the fastest means of transport.\",\"e\":\"\\u0939\\u0935\\u093e\\u0908 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0935\\u093f\\u092e\\u093e\\u0928 \\u0935 \\u0939\\u0947\\u0932\\u093f\\u0915\\u0949\\u092a\\u094d\\u091f\\u0930\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u0915\\u0947\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947. \\u0924\\u0940 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u091c\\u0932\\u0926 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0935\\u0947\\u0933\\u0947\\u091a\\u0940 \\u092c\\u091a\\u0924 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain why air transport is the most expensive means of transport.\",\"a\":\"Air transport requires high fuel, advanced technology, and maintenance, making it costly.\",\"e\":\"\\u0939\\u0935\\u093e\\u0908 \\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u0938\\u093e\\u0920\\u0940 \\u092e\\u0939\\u093e\\u0917 \\u0907\\u0902\\u0927\\u0928, \\u092a\\u094d\\u0930\\u0917\\u0924 \\u0924\\u0902\\u0924\\u094d\\u0930\\u091c\\u094d\\u091e\\u093e\\u0928 \\u0935 \\u0926\\u0947\\u0916\\u092d\\u093e\\u0932 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u0940 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u092e\\u0939\\u093e\\u0917 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u092e\\u093e\\u0928\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Explain the meaning of communication.\",\"a\":\"Communication means sharing or exchanging thoughts and feelings with others.\",\"e\":\"\\u0938\\u0902\\u0935\\u093e\\u0926 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0906\\u092a\\u0932\\u0947 \\u0935\\u093f\\u091a\\u093e\\u0930, \\u092d\\u093e\\u0935\\u0928\\u093e \\u0935 \\u092e\\u093e\\u0939\\u093f\\u0924\\u0940 \\u0907\\u0924\\u0930\\u093e\\u0902\\u0936\\u0940 \\u0935\\u093e\\u091f\\u0942\\u0928 \\u0918\\u0947\\u0923\\u0947 \\u0915\\u093f\\u0902\\u0935\\u093e \\u0926\\u0947\\u0935\\u093e\\u0923\\u0918\\u0947\\u0935\\u093e\\u0923 \\u0915\\u0930\\u0923\\u0947 \\u0939\\u094b\\u092f.\"},{\"q\":\"Describe how communication developed from early times to modern days.\",\"a\":\"Communication developed from gestures and signals to writing, postal services, and digital media.\",\"e\":\"\\u092a\\u094d\\u0930\\u093e\\u091a\\u0940\\u0928 \\u0915\\u093e\\u0933\\u093e\\u0924 \\u0938\\u0902\\u0915\\u0947\\u0924 \\u0935 \\u0939\\u093e\\u0935\\u092d\\u093e\\u0935\\u093e\\u0902\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u0938\\u0902\\u0935\\u093e\\u0926 \\u0938\\u093e\\u0927\\u0932\\u093e \\u091c\\u093e\\u0924 \\u0905\\u0938\\u0947. \\u0928\\u0902\\u0924\\u0930 \\u0932\\u0947\\u0916\\u0928, \\u091f\\u092a\\u093e\\u0932 \\u0938\\u0947\\u0935\\u093e \\u0906\\u0923\\u093f \\u0906\\u0927\\u0941\\u0928\\u093f\\u0915 \\u0915\\u093e\\u0933\\u093e\\u0924 \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e\\u093e\\u0902\\u091a\\u093e \\u0935\\u093e\\u092a\\u0930 \\u0939\\u094b\\u090a \\u0932\\u093e\\u0917\\u0932\\u093e.\"},{\"q\":\"Explain personal communication with examples.\",\"a\":\"Personal communication is communication with one or a few people, such as letters, phones, and emails.\",\"e\":\"\\u090f\\u0915\\u093e \\u0915\\u093f\\u0902\\u0935\\u093e \\u0915\\u093e\\u0939\\u0940 \\u0932\\u094b\\u0915\\u093e\\u0902\\u0936\\u0940 \\u0939\\u094b\\u0923\\u093e\\u0930\\u093e \\u0938\\u0902\\u0935\\u093e\\u0926 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0935\\u0948\\u092f\\u0915\\u094d\\u0924\\u093f\\u0915 \\u0938\\u0902\\u0935\\u093e\\u0926. \\u092a\\u0924\\u094d\\u0930, \\u0926\\u0942\\u0930\\u0927\\u094d\\u0935\\u0928\\u0940, \\u092e\\u094b\\u092c\\u093e\\u0908\\u0932 \\u0935 \\u0908-\\u092e\\u0947\\u0932 \\u0939\\u0940 \\u0924\\u094d\\u092f\\u093e\\u091a\\u0940 \\u0909\\u0926\\u093e\\u0939\\u0930\\u0923\\u0947 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Describe the role of the postal service as a means of communication.\",\"a\":\"The postal service is the oldest means of communication used to send letters and parcels.\",\"e\":\"\\u091f\\u092a\\u093e\\u0932 \\u0938\\u0947\\u0935\\u093e \\u0939\\u0940 \\u0938\\u0902\\u0935\\u093e\\u0926\\u093e\\u091a\\u0940 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u091c\\u0941\\u0928\\u0940 \\u092a\\u0926\\u094d\\u0927\\u0924 \\u0905\\u0938\\u0942\\u0928 \\u092a\\u0924\\u094d\\u0930\\u0947, \\u092a\\u093e\\u0930\\u094d\\u0938\\u0932 \\u0935 \\u092a\\u0948\\u0938\\u0947 \\u092a\\u093e\\u0920\\u0935\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u0940 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Explain mass communication and its importance.\",\"a\":\"Mass communication is communication with a large number of people at the same time.\",\"e\":\"\\u090f\\u0915\\u093e\\u091a \\u0935\\u0947\\u0933\\u0940 \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u092e\\u093e\\u0923\\u093e\\u0935\\u0930 \\u0932\\u094b\\u0915\\u093e\\u0902\\u092a\\u0930\\u094d\\u092f\\u0902\\u0924 \\u092a\\u094b\\u0939\\u094b\\u091a\\u0923\\u093e\\u0930\\u093e \\u0938\\u0902\\u0935\\u093e\\u0926 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u091c\\u0928\\u0938\\u0902\\u0935\\u093e\\u0926 \\u0939\\u094b\\u092f.\"},{\"q\":\"Describe the different means of mass communication.\",\"a\":\"Newspapers, magazines, radio, cinema, and television are means of mass communication.\",\"e\":\"\\u0935\\u0943\\u0924\\u094d\\u0924\\u092a\\u0924\\u094d\\u0930\\u0947, \\u092e\\u093e\\u0938\\u093f\\u0915\\u0947, \\u0930\\u0947\\u0921\\u093f\\u0913, \\u091a\\u093f\\u0924\\u094d\\u0930\\u092a\\u091f \\u0906\\u0923\\u093f \\u0926\\u0942\\u0930\\u0926\\u0930\\u094d\\u0936\\u0928 \\u0939\\u0940 \\u091c\\u0928\\u0938\\u0902\\u0935\\u093e\\u0926\\u093e\\u091a\\u0940 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0938\\u093e\\u0927\\u0928\\u0947 \\u0906\\u0939\\u0947\\u0924.\"}]','TRANSPORT AND COMMUNICATION','2026-01-16 17:37:08'),(28,82,'DIFFERENT OCCUPATIONS','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain the meaning of occupation and why people choose different occupations.\",\"a\":\"An occupation is any work done to earn money. People choose different occupations based on their skills, education, and interests.\",\"e\":\"\\u0909\\u092a\\u091c\\u0940\\u0935\\u093f\\u0915\\u0947\\u0938\\u093e\\u0920\\u0940 \\u0915\\u0947\\u0932\\u0947\\u0932\\u0947 \\u0915\\u094b\\u0923\\u0924\\u0947\\u0939\\u0940 \\u0915\\u093e\\u092e \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0939\\u094b\\u092f. \\u0932\\u094b\\u0915 \\u0906\\u092a\\u0932\\u0947 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923, \\u0915\\u094c\\u0936\\u0932\\u094d\\u092f\\u0947 \\u0906\\u0923\\u093f \\u0906\\u0935\\u0921\\u0940\\u0928\\u0941\\u0938\\u093e\\u0930 \\u0935\\u0947\\u0917\\u0935\\u0947\\u0917\\u0933\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0928\\u093f\\u0935\\u0921\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe farming as an important occupation in India.\",\"a\":\"Farming involves growing crops and rearing animals and is the main occupation of many people living in villages.\",\"e\":\"\\u0936\\u0947\\u0924\\u0940\\u092e\\u0927\\u094d\\u092f\\u0947 \\u092a\\u093f\\u0915\\u0947 \\u092a\\u093f\\u0915\\u0935\\u0923\\u0947 \\u0935 \\u092a\\u094d\\u0930\\u093e\\u0923\\u0940 \\u092a\\u093e\\u0933\\u0923\\u0947 \\u092f\\u093e \\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u092f\\u0947\\u0924\\u093e\\u0924. \\u092d\\u093e\\u0930\\u0924\\u093e\\u0924\\u0940\\u0932 \\u0905\\u0928\\u0947\\u0915 \\u0917\\u093e\\u0935\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0936\\u0947\\u0924\\u0940 \\u0939\\u093e \\u092e\\u0941\\u0916\\u094d\\u092f \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain the different crops grown through farming in India.\",\"a\":\"Farmers grow crops like wheat, rice, sugarcane, tea, coffee, fruits, and vegetables.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u0924\\u0940\\u0932 \\u0936\\u0947\\u0924\\u0915\\u0930\\u0940 \\u0917\\u0939\\u0942, \\u0924\\u093e\\u0902\\u0926\\u0942\\u0933, \\u090a\\u0938, \\u091a\\u0939\\u093e, \\u0915\\u0949\\u092b\\u0940 \\u0924\\u0938\\u0947\\u091a \\u092b\\u0933\\u0947 \\u0935 \\u092d\\u093e\\u091c\\u0940\\u092a\\u093e\\u0932\\u093e \\u0905\\u0936\\u0940 \\u0935\\u093f\\u0935\\u093f\\u0927 \\u092a\\u093f\\u0915\\u0947 \\u0918\\u0947\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe dairy farming and its importance.\",\"a\":\"Dairy farming involves rearing animals like cows and buffaloes for milk, meat, and other products.\",\"e\":\"\\u0926\\u0941\\u0917\\u094d\\u0927\\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f\\u093e\\u0924 \\u0917\\u093e\\u092f\\u0940, \\u092e\\u094d\\u0939\\u0936\\u0940, \\u0936\\u0947\\u0933\\u094d\\u092f\\u093e \\u0907\\u0924\\u094d\\u092f\\u093e\\u0926\\u0940 \\u092a\\u094d\\u0930\\u093e\\u0923\\u0940 \\u092a\\u093e\\u0933\\u0942\\u0928 \\u0926\\u0942\\u0927, \\u092e\\u093e\\u0902\\u0938 \\u0935 \\u0907\\u0924\\u0930 \\u0909\\u0924\\u094d\\u092a\\u093e\\u0926\\u0928\\u0947 \\u092e\\u093f\\u0933\\u0935\\u0932\\u0940 \\u091c\\u093e\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain poultry farming as an occupation.\",\"a\":\"Poultry farming involves rearing birds like hens and ducks to produce eggs and meat.\",\"e\":\"\\u0915\\u0941\\u0915\\u094d\\u0915\\u0941\\u091f\\u092a\\u093e\\u0932\\u0928\\u093e\\u0924 \\u0915\\u094b\\u0902\\u092c\\u0921\\u094d\\u092f\\u093e, \\u092c\\u0926\\u0915\\u0947 \\u0907\\u0924\\u094d\\u092f\\u093e\\u0926\\u0940 \\u092a\\u0915\\u094d\\u0937\\u0940 \\u092a\\u093e\\u0933\\u0942\\u0928 \\u0905\\u0902\\u0921\\u0940 \\u0935 \\u092e\\u093e\\u0902\\u0938 \\u0909\\u0924\\u094d\\u092a\\u093e\\u0926\\u0928 \\u0915\\u0947\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Describe fishing as an occupation practised in India.\",\"a\":\"Fishing is the occupation of catching fish and is common in coastal areas and near water bodies.\",\"e\":\"\\u092e\\u093e\\u0938\\u0947\\u092e\\u093e\\u0930\\u0940 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u092e\\u093e\\u0938\\u0947 \\u092a\\u0915\\u0921\\u0923\\u094d\\u092f\\u093e\\u091a\\u093e \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0939\\u094b\\u092f. \\u0924\\u094b \\u092a\\u094d\\u0930\\u093e\\u092e\\u0941\\u0916\\u094d\\u092f\\u093e\\u0928\\u0947 \\u0915\\u093f\\u0928\\u093e\\u0930\\u0940 \\u092d\\u093e\\u0917\\u093e\\u0924 \\u0924\\u0938\\u0947\\u091a \\u0928\\u0926\\u094d\\u092f\\u093e, \\u0924\\u0932\\u093e\\u0935\\u093e\\u0902\\u091c\\u0935\\u0933 \\u0915\\u0947\\u0932\\u093e \\u091c\\u093e\\u0924\\u094b.\"},{\"q\":\"Explain the importance of fishing for food and trade.\",\"a\":\"Fishing provides an important source of food and helps in earning money through exports.\",\"e\":\"\\u092e\\u093e\\u0938\\u0947 \\u0939\\u0947 \\u0905\\u0928\\u094d\\u0928\\u093e\\u091a\\u0947 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u0938\\u094d\\u0930\\u094b\\u0924 \\u0906\\u0939\\u0947\\u0924 \\u0924\\u0938\\u0947\\u091a \\u092e\\u093e\\u0938\\u0947\\u092e\\u093e\\u0930\\u0940\\u092e\\u0941\\u0933\\u0947 \\u0928\\u093f\\u0930\\u094d\\u092f\\u093e\\u0924\\u0940\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u0909\\u0924\\u094d\\u092a\\u0928\\u094d\\u0928 \\u092e\\u093f\\u0933\\u0924\\u0947.\"},{\"q\":\"Describe forestry and the activities involved in it.\",\"a\":\"Forestry involves collecting wood, gum, honey, rubber, and herbs from forests.\",\"e\":\"\\u0935\\u0928\\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f\\u093e\\u0924 \\u091c\\u0902\\u0917\\u0932\\u093e\\u0924\\u0942\\u0928 \\u0932\\u093e\\u0915\\u0942\\u0921, \\u0917\\u094b\\u0902\\u0926, \\u092e\\u0927, \\u0930\\u092c\\u0930 \\u0935 \\u0914\\u0937\\u0927\\u0940 \\u0935\\u0928\\u0938\\u094d\\u092a\\u0924\\u0940 \\u0917\\u094b\\u0933\\u093e \\u0915\\u0947\\u0932\\u094d\\u092f\\u093e \\u091c\\u093e\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain why forestry is important for people living near forests.\",\"a\":\"Forestry helps people living near forests earn their livelihood.\",\"e\":\"\\u091c\\u0902\\u0917\\u0932\\u093e\\u091c\\u0935\\u0933 \\u0930\\u093e\\u0939\\u0923\\u093e\\u0931\\u094d\\u092f\\u093e \\u0932\\u094b\\u0915\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940 \\u0935\\u0928\\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0939\\u093e \\u0909\\u092a\\u091c\\u0940\\u0935\\u093f\\u0915\\u0947\\u091a\\u093e \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u093e \\u0938\\u094d\\u0930\\u094b\\u0924 \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe mining as an occupation.\",\"a\":\"Mining is the process of digging minerals like coal, iron, and copper from the ground.\",\"e\":\"\\u0916\\u0928\\u093f\\u091c\\u0947 \\u091c\\u092e\\u093f\\u0928\\u0940\\u0924\\u0942\\u0928 \\u0916\\u094b\\u0926\\u0942\\u0928 \\u0915\\u093e\\u0922\\u0923\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u0947\\u0932\\u093e \\u0916\\u093e\\u0923\\u0915\\u093e\\u092e \\u0915\\u093f\\u0902\\u0935\\u093e \\u0916\\u0928\\u0928 \\u0905\\u0938\\u0947 \\u092e\\u094d\\u0939\\u0923\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the importance of mining in industrial development.\",\"a\":\"Mining provides raw materials needed to make machines, vehicles, and other products.\",\"e\":\"\\u0916\\u0928\\u0928\\u093e\\u0924\\u0942\\u0928 \\u092e\\u093f\\u0933\\u0923\\u093e\\u0930\\u0940 \\u0916\\u0928\\u093f\\u091c\\u0947 \\u0909\\u0926\\u094d\\u092f\\u094b\\u0917\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940 \\u0915\\u091a\\u094d\\u091a\\u093e \\u092e\\u093e\\u0932 \\u092a\\u0941\\u0930\\u0935\\u0924\\u093e\\u0924, \\u091c\\u094d\\u092f\\u093e\\u0924\\u0942\\u0928 \\u092f\\u0902\\u0924\\u094d\\u0930\\u0947 \\u0935 \\u0907\\u0924\\u0930 \\u0935\\u0938\\u094d\\u0924\\u0942 \\u0924\\u092f\\u093e\\u0930 \\u0939\\u094b\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe the occupations found in cities and towns.\",\"a\":\"People in cities work in offices, factories, shops, hospitals, and run businesses.\",\"e\":\"\\u0936\\u0939\\u0930\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0932\\u094b\\u0915 \\u0915\\u093e\\u0930\\u094d\\u092f\\u093e\\u0932\\u092f\\u0947, \\u0915\\u093e\\u0930\\u0916\\u093e\\u0928\\u0947, \\u0926\\u0941\\u0915\\u093e\\u0928\\u0947, \\u0930\\u0941\\u0917\\u094d\\u0923\\u093e\\u0932\\u092f\\u0947 \\u092f\\u0947\\u0925\\u0947 \\u0915\\u093e\\u092e \\u0915\\u0930\\u0924\\u093e\\u0924 \\u0924\\u0938\\u0947\\u091a \\u0938\\u094d\\u0935\\u0924\\u0903\\u091a\\u093e \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the role of factories as workplaces.\",\"a\":\"Factories convert raw materials into useful finished products.\",\"e\":\"\\u0915\\u093e\\u0930\\u0916\\u093e\\u0928\\u094d\\u092f\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0915\\u091a\\u094d\\u091a\\u093e \\u092e\\u093e\\u0932 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u0930\\u0942\\u0928 \\u0909\\u092a\\u092f\\u0941\\u0915\\u094d\\u0924 \\u0935\\u0938\\u094d\\u0924\\u0942\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930 \\u0915\\u0947\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Describe skilled occupations with examples.\",\"a\":\"Skilled occupations involve special skills like carpentry, pottery, jewellery making, and electrician work.\",\"e\":\"\\u0915\\u094c\\u0936\\u0932\\u094d\\u092f\\u093e\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0938\\u0941\\u0924\\u093e\\u0930\\u0915\\u093e\\u092e, \\u0915\\u0941\\u0902\\u092d\\u093e\\u0930\\u0915\\u093e\\u092e, \\u0926\\u093e\\u0917\\u093f\\u0928\\u0947\\u0928\\u093f\\u0930\\u094d\\u092e\\u093f\\u0924\\u0940 \\u0935 \\u0935\\u093f\\u091c\\u0924\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0915\\u093e\\u092e \\u092f\\u093e\\u0902\\u091a\\u093e \\u0938\\u092e\\u093e\\u0935\\u0947\\u0936 \\u0939\\u094b\\u0924\\u094b.\"},{\"q\":\"Summarise the importance of different occupations in society.\",\"a\":\"Different occupations help meet the needs of society and support economic development.\",\"e\":\"\\u0935\\u0947\\u0917\\u0935\\u0947\\u0917\\u0933\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0938\\u092e\\u093e\\u091c\\u093e\\u091a\\u094d\\u092f\\u093e \\u0917\\u0930\\u091c\\u093e \\u092a\\u0942\\u0930\\u094d\\u0923 \\u0915\\u0930\\u0924\\u093e\\u0924 \\u0906\\u0923\\u093f \\u0906\\u0930\\u094d\\u0925\\u093f\\u0915 \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0924 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u092d\\u0942\\u092e\\u093f\\u0915\\u093e \\u092c\\u091c\\u093e\\u0935\\u0924\\u093e\\u0924.\"}]','DIFFERENT OCCUPATIONS','2026-01-16 17:39:36'),(29,83,'OUR ENVIRONMENT','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain what is meant by environment and describe its main components.\",\"a\":\"Environment means everything that surrounds us and includes both living and non-living things.\",\"e\":\"\\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0906\\u092a\\u0932\\u094d\\u092f\\u093e \\u0906\\u091c\\u0942\\u092c\\u093e\\u091c\\u0942\\u091a\\u0940 \\u0938\\u0930\\u094d\\u0935 \\u0938\\u091c\\u0940\\u0935 \\u0935 \\u0928\\u093f\\u0930\\u094d\\u091c\\u0940\\u0935 \\u0918\\u091f\\u0915\\u093e\\u0902\\u091a\\u0940 \\u090f\\u0915\\u0924\\u094d\\u0930\\u093f\\u0924 \\u0930\\u091a\\u0928\\u093e \\u0939\\u094b\\u092f. \\u092e\\u093e\\u0923\\u0938\\u0947, \\u092a\\u094d\\u0930\\u093e\\u0923\\u0940, \\u0935\\u0928\\u0938\\u094d\\u092a\\u0924\\u0940 \\u0924\\u0938\\u0947\\u091a \\u0939\\u0935\\u093e, \\u092a\\u093e\\u0923\\u0940, \\u091c\\u092e\\u0940\\u0928 \\u0939\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u093e\\u091a\\u0947 \\u0918\\u091f\\u0915 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Describe the difference between living and non-living things in the environment.\",\"a\":\"Living things grow and breathe, while non-living things do not have life.\",\"e\":\"\\u0938\\u091c\\u0940\\u0935 \\u0935\\u0938\\u094d\\u0924\\u0942\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0935\\u093e\\u0922, \\u0936\\u094d\\u0935\\u0938\\u0928 \\u0935 \\u0939\\u093e\\u0932\\u091a\\u093e\\u0932 \\u0905\\u0938\\u0924\\u0947, \\u0924\\u0930 \\u0928\\u093f\\u0930\\u094d\\u091c\\u0940\\u0935 \\u0935\\u0938\\u094d\\u0924\\u0942\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u091c\\u0940\\u0935\\u0928 \\u0928\\u0938\\u0924\\u0947.\"},{\"q\":\"Explain the meaning of pollution and its impact on the environment.\",\"a\":\"Pollution is the dirtying of the environment by harmful substances called pollutants.\",\"e\":\"\\u0939\\u093e\\u0928\\u0940\\u0915\\u093e\\u0930\\u0915 \\u092a\\u0926\\u093e\\u0930\\u094d\\u0925 \\u0935\\u093e\\u0924\\u093e\\u0935\\u0930\\u0923\\u093e\\u0924 \\u092e\\u093f\\u0938\\u0933\\u0932\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923 \\u0926\\u0942\\u0937\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947, \\u092f\\u093e\\u0932\\u093e\\u091a \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u092e\\u094d\\u0939\\u0923\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe air pollution along with its causes.\",\"a\":\"Air pollution occurs due to smoke from vehicles, factories, burning waste, and firecrackers.\",\"e\":\"\\u0935\\u093e\\u0939\\u0928\\u093e\\u0902\\u091a\\u093e \\u0927\\u0942\\u0930, \\u0915\\u093e\\u0930\\u0916\\u093e\\u0928\\u094d\\u092f\\u093e\\u0902\\u091a\\u093e \\u0927\\u0942\\u0930, \\u0915\\u091a\\u0930\\u093e \\u091c\\u093e\\u0933\\u0923\\u0947 \\u0935 \\u092b\\u091f\\u093e\\u0915\\u0947 \\u092b\\u094b\\u0921\\u0923\\u0947 \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0935\\u093e\\u092f\\u0942 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain the effects of air pollution on human health.\",\"a\":\"Air pollution causes breathing problems, headaches, and allergies.\",\"e\":\"\\u0935\\u093e\\u092f\\u0942 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0936\\u094d\\u0935\\u0938\\u0928\\u093e\\u091a\\u0947 \\u0935\\u093f\\u0915\\u093e\\u0930, \\u0921\\u094b\\u0915\\u0947\\u0926\\u0941\\u0916\\u0940, \\u0921\\u094b\\u0933\\u0947 \\u0935 \\u0928\\u093e\\u0915\\u093e\\u091a\\u0940 \\u091c\\u0933\\u091c\\u0933 \\u0939\\u094b\\u090a \\u0936\\u0915\\u0924\\u0947.\"},{\"q\":\"Describe water pollution and its major causes.\",\"a\":\"Water pollution happens when waste and harmful substances are dumped into water bodies.\",\"e\":\"\\u0928\\u0926\\u094d\\u092f\\u093e, \\u0924\\u0932\\u093e\\u0935 \\u0935 \\u092a\\u093e\\u0923\\u0935\\u0920\\u094d\\u092f\\u093e\\u0924 \\u0915\\u091a\\u0930\\u093e \\u0935 \\u0918\\u093e\\u0924\\u0915 \\u0926\\u094d\\u0930\\u0935\\u094d\\u092f\\u0947 \\u091f\\u093e\\u0915\\u0932\\u094d\\u092f\\u093e\\u0928\\u0947 \\u091c\\u0932\\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain the harmful effects of water pollution.\",\"a\":\"Water pollution causes diseases and harms aquatic plants and animals.\",\"e\":\"\\u091c\\u0932\\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0905\\u0924\\u093f\\u0938\\u093e\\u0930, \\u0915\\u0949\\u0932\\u0930\\u093e, \\u092a\\u093f\\u0935\\u0933\\u094d\\u092f\\u093e \\u0915\\u093e\\u0935\\u0933\\u0940\\u0938\\u093e\\u0930\\u0916\\u0947 \\u0906\\u091c\\u093e\\u0930 \\u0939\\u094b\\u0924\\u093e\\u0924 \\u0924\\u0938\\u0947\\u091a \\u091c\\u0932\\u091c\\u0940\\u0935\\u093e\\u0902\\u0928\\u093e \\u0928\\u0941\\u0915\\u0938\\u093e\\u0928 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe noise pollution and list its causes.\",\"a\":\"Noise pollution is caused by loud sounds from vehicles, machines, and loudspeakers.\",\"e\":\"\\u0905\\u0924\\u093f\\u091c\\u094b\\u0930\\u093e\\u091a\\u093e \\u0906\\u0935\\u093e\\u091c, \\u0935\\u093e\\u0939\\u0928\\u093e\\u0902\\u091a\\u0947 \\u0939\\u0949\\u0930\\u094d\\u0928, \\u092f\\u0902\\u0924\\u094d\\u0930\\u0938\\u093e\\u092e\\u0917\\u094d\\u0930\\u0940 \\u0935 \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u0906\\u0935\\u093e\\u091c\\u093e\\u0924\\u0940\\u0932 \\u0938\\u0902\\u0917\\u0940\\u0924\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0927\\u094d\\u0935\\u0928\\u0940 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain the effects of noise pollution on people.\",\"a\":\"Noise pollution causes headache, sleep disturbance, and hearing loss.\",\"e\":\"\\u0927\\u094d\\u0935\\u0928\\u0940 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0921\\u094b\\u0915\\u0947\\u0926\\u0941\\u0916\\u0940, \\u091d\\u094b\\u092a\\u0947\\u091a\\u093e \\u0924\\u094d\\u0930\\u093e\\u0938 \\u0935 \\u0910\\u0915\\u0923\\u094d\\u092f\\u093e\\u091a\\u0940 \\u0915\\u094d\\u0937\\u092e\\u0924\\u093e \\u0915\\u092e\\u0940 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe land pollution with suitable examples.\",\"a\":\"Land pollution occurs due to dumping garbage, plastic waste, and chemicals on land.\",\"e\":\"\\u091c\\u092e\\u093f\\u0928\\u0940\\u0935\\u0930 \\u0915\\u091a\\u0930\\u093e, \\u092a\\u094d\\u0932\\u093e\\u0938\\u094d\\u091f\\u093f\\u0915 \\u0935 \\u0930\\u093e\\u0938\\u093e\\u092f\\u0928\\u093f\\u0915 \\u092a\\u0926\\u093e\\u0930\\u094d\\u0925 \\u091f\\u093e\\u0915\\u0932\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092d\\u0942\\u092e\\u0940 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain the effects of land pollution on the surroundings.\",\"a\":\"Land pollution causes spread of diseases and spoils natural beauty.\",\"e\":\"\\u092d\\u0942\\u092e\\u0940 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0930\\u094b\\u0917\\u0930\\u093e\\u0908 \\u092a\\u0938\\u0930\\u0924\\u0947 \\u0906\\u0923\\u093f \\u092a\\u0930\\u093f\\u0938\\u0930\\u093e\\u091a\\u0947 \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f \\u0928\\u0937\\u094d\\u091f \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe the Three R\\u2019s used to save the environment.\",\"a\":\"The Three R\\u2019s are Reduce, Reuse, and Recycle.\",\"e\":\"\\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923 \\u0935\\u093e\\u091a\\u0935\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0915\\u092e\\u0940 \\u0935\\u093e\\u092a\\u0930 (Reduce), \\u092a\\u0941\\u0928\\u094d\\u0939\\u093e \\u0935\\u093e\\u092a\\u0930 (Reuse) \\u0906\\u0923\\u093f \\u092a\\u0941\\u0928\\u0930\\u094d\\u0935\\u093e\\u092a\\u0930\\u093e\\u0924\\u0942\\u0928 \\u0928\\u093f\\u0930\\u094d\\u092e\\u093f\\u0924\\u0940 (Recycle) \\u092f\\u093e \\u0924\\u0940\\u0928 \\u0928\\u093f\\u092f\\u092e\\u093e\\u0902\\u091a\\u093e \\u0905\\u0935\\u0932\\u0902\\u092c \\u0915\\u0947\\u0932\\u093e \\u091c\\u093e\\u0924\\u094b.\"},{\"q\":\"Explain how reducing waste helps the environment.\",\"a\":\"Reducing waste decreases pollution and conserves natural resources.\",\"e\":\"\\u0915\\u091a\\u0930\\u093e \\u0915\\u092e\\u0940 \\u0915\\u0947\\u0932\\u094d\\u092f\\u093e\\u0938 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0918\\u091f\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0928\\u0948\\u0938\\u0930\\u094d\\u0917\\u093f\\u0915 \\u0938\\u093e\\u0927\\u0928\\u0938\\u0902\\u092a\\u0924\\u094d\\u0924\\u0940\\u091a\\u0947 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe personal actions that help in saving the environment.\",\"a\":\"Planting trees, avoiding plastic, and saving water help protect the environment.\",\"e\":\"\\u091d\\u093e\\u0921\\u0947 \\u0932\\u093e\\u0935\\u0923\\u0947, \\u092a\\u094d\\u0932\\u093e\\u0938\\u094d\\u091f\\u093f\\u0915 \\u091f\\u093e\\u0933\\u0923\\u0947, \\u092a\\u093e\\u0923\\u0940 \\u0935 \\u0935\\u0940\\u091c \\u0935\\u093e\\u091a\\u0935\\u0923\\u0947 \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u093e\\u091a\\u0947 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Summarise why protecting the environment is important for future generations.\",\"a\":\"Protecting the environment ensures healthy living and resources for the future.\",\"e\":\"\\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u093e\\u091a\\u0947 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0915\\u0947\\u0932\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092d\\u0935\\u093f\\u0937\\u094d\\u092f\\u093e\\u0924\\u0940\\u0932 \\u092a\\u093f\\u0922\\u094d\\u092f\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094b\\u0917\\u0940 \\u091c\\u0940\\u0935\\u0928 \\u0935 \\u0938\\u0902\\u0938\\u093e\\u0927\\u0928\\u0947 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0930\\u093e\\u0939\\u0924\\u093e\\u0924.\"}]','OUR ENVIRONMENT','2026-01-16 17:41:45');
